-- mod-dnd: treats - small discoveries off the beaten path (generated by tools/make_treats_sql.py)
DROP TABLE IF EXISTS `dnd_treat`;
CREATE TABLE `dnd_treat` (
  `id` INT UNSIGNED NOT NULL,
  `map` INT UNSIGNED NOT NULL,
  `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL, `o` FLOAT NOT NULL,
  `passive` TINYINT NOT NULL DEFAULT 0,
  `skill` VARCHAR(32) NOT NULL DEFAULT 'Perception',
  `dc` TINYINT NOT NULL DEFAULT 12,
  `req` VARCHAR(32) NOT NULL DEFAULT '',
  `free_for` VARCHAR(32) NOT NULL DEFAULT '',
  `tell_guid` INT UNSIGNED NOT NULL DEFAULT 0,
  `radius` FLOAT NOT NULL DEFAULT 10,
  `money` INT UNSIGNED NOT NULL DEFAULT 0,
  `item` INT UNSIGNED NOT NULL DEFAULT 0,
  `item_count` INT UNSIGNED NOT NULL DEFAULT 1,
  `flag` VARCHAR(32) NOT NULL DEFAULT '',
  `text_look` TEXT, `text_found` TEXT, `text_success` TEXT, `text_fail` TEXT, `text_claim` TEXT, `text_free` TEXT,
  `game` VARCHAR(16) NOT NULL DEFAULT '',
  `hint` VARCHAR(32) NOT NULL DEFAULT '',
  `grant_skill` VARCHAR(32) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `dnd_treat` VALUES
(1, 0, -6524.630, 362.427, 388.329, -2.7576, 1, 'Perception', 13, '', '', 9001001, 10, 0, 0, 1, 'whelptoken', 'A heap of troll skulls and bones, crusted with frost - an offering, or a warning.', 'Something small and pale lies among the skulls - and it isn''t bone.', '', '', 'A whelp''s token: a tusk carved into a crude little wolf, a name scratched into it in Zandali. Someone made this for someone they cared about - and it''s been thrown away here, among Grik''nir''s offerings.', '', '', '', ''),
(2, 0, -6507.270, 688.761, 387.274, -0.3142, 0, 'Investigation', 10, '', '', 9001002, 10, 3500, 954, 1, '', '', '', 'The sledge''s seat is nailed down over a box-bed. With the boards levered up: the driver''s strongbox, its lock rusted through - a handful of silver, and a waybill - ''Kharanos to Anvilmar. Mountaineer rations. Turned back at the trogg line.'' Someone has added underneath, in a different hand: ''AGAIN.''', 'You dig through splintered planks and frozen sacking. Whatever was worth taking, someone took it first.', ' Tucked in with it: a Scroll of Healing Word.', '', 'pry', '', ''),
(3, 0, -6374.810, 773.704, 386.213, -1.4312, 1, 'Perception', 14, '', '', 9001003, 10, 0, 0, 1, 'compass', 'A supply crate lies split open in the snow, its contents long since scattered.', 'Half-buried in the snow beside the crate, something catches the light.', '', '', 'A brass compass, cracked but still swinging north. Trogg teeth-marks on the casing - one of them must have dropped it running. Troggs do love anything shiny.', '', '', '', ''),
(4, 0, -6222.470, 688.973, 385.002, 4.9742, 0, 'Survival', 13, '', '', 9001004, 10, 1500, 118, 1, '', '', '', 'The stones are heaped too neatly for a rockfall - snow packed between them by hand, a stake hammered in for a marker. You dig. A hunter''s cache: dried meat gone hard as wood, a stoppered red vial, and a pouch of coins.', 'Just stones with snow banked against them. Or maybe not - but you can''t tell where you''d even start digging.', '', '', 'dig', '', ''),
(5, 0, -6235.870, 152.989, 428.399, 2.0420, 0, 'Perception', 12, '', '', 9001005, 10, 0, 0, 1, 'lookout', '', '', 'You climb the crumbling old lookout, hold by hold. From the top you can see the whole south of the valley. Smoke curls up from the troll camp beyond the ridge - and now you see it: a gap in their bone fence on the west side, out of sight of the throne.', 'Snow-glare and wind. Whatever''s down there, you can''t make it out from up here.', '', '', 'climb', '', ''),
(6, 0, -6364.170, 235.656, 393.626, 1.6181, 0, 'History', 14, '', 'Dwarf', 9001006, 10, 5000, 0, 1, '', '', '', 'Old Khaz runes, half scoured away by the wind: ''Here the Ironforge surveyors cached their wages against the trogg-winter.'' Beneath the stone, wrapped in oilcloth, a little purse of old coins.', 'Runes. Old ones. Whatever they say, they''re keeping it to themselves.', '', 'Your eyes read the old Khaz runes at a glance.', 'runes', '', ''),
(7, 0, -6490.650, 512.377, 387.494, 0.9250, 0, 'Medicine', 12, '', '', 9001007, 10, 0, 0, 1, 'frostburn', '', '', 'A mountaineer, a few weeks dead; the cold has kept him. Three long gouges across his chest are rimed with ice that never melts - frost-burns, from claws. No animal did this. The Frostmane have a master who fights with frozen claws.', 'Long dead, and the cold has kept him. How he died, you can''t say.', '', '', '', '', ''),
(8, 0, -6484.930, 294.773, 372.653, 2.4958, 0, 'Sleight of Hand', 13, '', '', 9001008, 10, 1200, 4307, 1, '', '', '', 'The old lock gives with a click. Inside: a mountaineer''s spare gloves, worn to the shape of a climber''s grip, and a little bag of coins, wrapped against the damp.', 'The lock is rusted solid, and your pick snaps in it.', '', '', 'lock', '', ''),
(9, 0, -6581.860, 319.805, 386.869, 5.1923, 1, 'Perception', 14, '', '', 9001009, 10, 900, 2290, 1, '', 'A little shrine of bones and frost-chalk, half fallen over.', 'Something bright lies under the toppled stones. Set them back up, carefully, the way they stood.', '', '', 'A troll offering-bead of blue glass, cold to the touch even in your palm. Pretty, and probably worth a few coins to someone. Tucked in with it: a Scroll of Magic Missile.', '', 'stack', '', ''),
(10, 0, -6176.970, 254.691, 386.853, 1.1644, 0, 'Survival', 10, '', '', 9001010, 10, 800, 0, 1, '', '', '', 'Wolf sign, and old. You follow the drag of their kill back along the ridge to where it fell, and under the bones there you find what the poor beast was carrying: a forgotten pouch of coins, the drawstring chewed to a wet knot.', 'Bones, picked clean. The wolves leave nothing for anyone else.', '', '', 'tracks', '', ''),
(11, 0, -6289.810, 628.378, 387.717, 1.8356, 1, 'Perception', 13, '', '', 9001011, 10, 0, 118, 1, '', 'A crate the troggs have smashed open and lost interest in.', 'Wedged in the broken slats: a stoppered vial they missed.', '', '', 'A small red healing draught, still sealed. The troggs must not have known what it was.', '', '', '', ''),
(12, 0, -6244.870, 778.502, 387.100, 1.9426, 0, 'Arcana', 14, '', '', 9001012, 10, 2500, 118, 2, '', '', '', 'The frost on the stone isn''t natural - it''s a ward, old and patient, and it is listening. Not for a word: for a tune. Four notes, sung to it in the right order, and it will let go of whatever it''s keeping cold.', 'Frost on a stone. If there''s more to it, it isn''t telling you.', '', '', 'song', 'bard_air', ''),
(13, 0, -6438.840, 745.375, 390.138, 6.2119, 1, 'Perception', 11, '', '', 9001013, 10, 400, 0, 1, '', 'A low heap of stones and snow where the boars have been rooting.', 'The boars have dug something up and lost interest in it.', '', '', 'A dented tin of dwarven tea, and a few coppers tucked in the lid. The boars clearly preferred the turnips.', '', '', '', ''),
(14, 0, -6495.360, 619.654, 388.123, 5.9340, 0, 'Athletics', 14, '', '', 9001014, 10, 0, 118, 1, '', '', '', 'You heave the sledge over. Underneath, flattened but intact: a hunter''s bundle with dried meat and a healing draught.', 'The sledge is frozen to the ground and won''t move an inch.', '', '', '', '', ''),
(15, 0, -6296.630, 244.471, 390.969, 1.8394, 0, 'Investigation', 13, '', '', 9001015, 10, 1100, 0, 1, 'whistle', '', '', 'A trogg''s bedding of gnawed bones and rags - and wrapped in the rags, its hoard: bent nails, a cracked spoon, a few honest coins the creature clearly thought were the least interesting thing it owned - and a mountaineer''s brass whistle. You try it. It is astonishingly loud; something small and furry bolts out of the rocks a hundred paces off.', 'Gnawed bones and rags that smell exactly as bad as they look. You give up before your nose does.', '', '', '', '', ''),
(16, 0, -6277.200, 552.383, 387.634, 4.2680, 0, 'Athletics', 13, '', '', 9001016, 10, 0, 118, 1, '', '', '', 'You get your shoulder under the crate and heave it off the rock that pinned it. The bottom slats hold a mountaineer''s emergency kit: a coil of rope, flint, and a healing draught still in its straw.', 'The crate is wedged fast under a fallen slab. You strain until your back complains, and it doesn''t budge.', '', '', '', '', ''),
(17, 0, -6329.100, 746.326, 387.314, 5.9240, 1, 'Perception', 13, '', '', 9001017, 10, 1600, 0, 1, '', 'A cold campfire ringed with flat stones. Someone sat here for a long while, not so long ago.', 'One of the ring stones has been lifted and put back - the frost under it is broken.', '', '', 'Under the stone, a scout''s tally-stick notched with trogg sightings, and the scout''s pay, never collected.', '', '', '', ''),
(18, 0, -6464.960, 437.660, 415.774, 2.2815, 0, 'Arcana', 13, '', 'Wizard', 9001018, 10, 700, 118, 1, '', '', '', 'A ward-stone, set high where the wind keeps it clear of snow. Its keeping charm still glows, faint and stubborn, and you put it out glyph by glyph. Behind it, in a dry niche, a traveller left offerings for safe passage: coins, and a sealed vial.', 'Weathered marks on a stone. Pretty, in a way.', '', 'You know a keeping-charm when you see one.', 'wards', '', ''),
(19, 0, -6424.570, 242.535, 410.675, 3.7746, 0, 'Sleight of Hand', 15, '', '', 9001019, 10, 0, 3039, 1, '', '', '', 'A dwarven strongbox with a tumbler dial, stiff with cold and made by someone who took pride in it. It gives - eventually. Inside, packed in oiled wool: a short bow of pale ash, the grip worn to the shape of one hand, strung and true after all this time. Someone meant to come back for it.', 'The tumblers won''t catch. Whoever locked this knew their business.', '', '', 'dial', '', ''),
(20, 0, -6113.430, 600.665, 399.993, 1.8968, 1, 'Perception', 15, '', '', 9001020, 10, 1200, 3103, 1, '', 'Snow has drifted over a heap of stones against a boulder on the hillside, smooth and untouched.', 'The drift isn''t quite smooth: the end of a wooden haft pokes out of it, bound in frozen leather.', '', '', 'A frozen satchel, lost by some long-gone traveller, the coins inside cold enough to sting - and beside it the thing the haft belongs to: a great two-handed hammer with the Coldridge mountaineers'' ram stamped on the head. The frost falls off it in one piece. It was made to be used.', '', 'dig', '', ''),
(21, 0, -6300.600, 381.503, 380.328, 0.0152, 0, 'Survival', 12, '', 'Barbarian', 9001021, 10, 900, 0, 1, '', '', '', 'A ring of boar skulls - a young wolf''s den marker, and the tracks say the yearling is out hunting. You circle in downwind and reach into the hollow behind the skulls before it''s back: a hunter''s dropped coin pouch, chewed but whole, tucked among the bones.', 'Skulls in a ring, scattered tracks. Somewhere behind them, something growls. You leave them be.', '', 'You know a den marker when you see one, and how long its owner stays away.', '', '', ''),
(22, 0, -6529.950, 681.262, 396.788, 1.1812, 0, 'Nature', 12, '', '', 9001022, 10, 0, 2139, 1, '', '', '', 'Not a kill - a ram that slipped from the ledge above and broke its neck. Its pack was still lashed on: a herder''s lunch long since frozen solid, and a little dwarven dagger in a fleece-lined sheath.', 'An old carcass. The crows got here first, and they don''t share.', '', '', '', '', ''),
(23, 0, -6394.900, 652.947, 386.861, 4.4713, 1, 'Perception', 13, '', '', 9001023, 10, 0, 1210, 1, '', 'A tumble of grey stones, split by a hundred winters of frost.', 'One of the stones is too round - and far too heavy for its size.', '', '', 'A geode, hollow and lined with amethyst teeth the colour of dusk. Prised loose, the best of the crystals makes a fine dark gem - a jeweller would pay for it.', '', 'geode', '', ''),
(24, 0, -6147.000, 753.035, 392.022, 6.1822, 0, 'Nature', 12, '', '', 9001024, 10, 2600, 0, 1, '', '', '', 'Most of these are plain mountain stone, but one has the knobbly rind of a geode, the kind the frost squeezes out of the cliffs. Inside: crystal, clean and bright. Enough loose shards to fill a purse.', 'Stones. If one of them is any different from the others, you can''t tell which.', '', '', 'geode', '', ''),
(25, 0, -6245.590, 461.450, 386.191, 4.0237, 1, 'Perception', 13, '', '', 9001025, 10, 0, 118, 1, '', 'A block of old blue ice, left behind where a stream used to run off the slope.', 'There''s something dark frozen in the middle of the ice.', '', '', 'A healing draught in a stoppered flask, frozen solid in the middle of a fall - and none the worse for it once it thaws in your hand.', '', 'ice', '', ''),
(26, 0, -6342.140, 482.296, 381.859, 2.5200, 0, 'Survival', 13, '', '', 9001026, 10, 1400, 0, 1, '', '', '', 'Old ice has seams, if you know where to look - and this has one, right down the middle. Frozen in the heart of it: a hunter''s coin pouch, lost through a crack in the stream one winter.', 'The ice is as hard as iron and you can''t find a seam to work at.', '', '', 'ice', '', ''),
(27, 0, -6410.020, 349.491, 389.741, 0.5967, 0, 'Medicine', 13, '', '', 9001027, 10, 900, 0, 1, '', '', '', 'A trapper, long dead, a broken leg splinted with his own snare-poles - and splinted well. He crawled this far. In his coat, a pouch of trade coin, a note to someone called Brenna, and his notebook: every beast of the valley, how it thinks, what calms it and what never will. You read it twice.', 'Old bones and old rags. Whatever happened here happened a long time ago.', '', '', '', '', 'Animal Handling'),
(28, 0, -6208.340, 605.062, 393.214, 6.1180, 1, 'Perception', 10, '', '', 9001028, 10, 300, 2580, 1, '', 'A crate the troggs have chewed on - actually chewed, the corners gnawed round.', 'A bundle wrapped in oilcloth has rolled under the crate.', '', '', 'A thick wool cape, oddly warm, and a few coppers knotted into its hem. The troggs went for the wood.', '', '', '', ''),
(29, 0, -6574.320, 409.030, 387.516, 0.0059, 0, 'Religion', 13, '', '', 9001029, 10, 1000, 0, 1, '', '', '', 'A whelp''s first shrine: three small skulls set in a row, each with a bead pushed into the eye socket. Frostmane children make these to be noticed by the loa. The beads are silver.', 'Little skulls in a row. A game? A warning? You leave them be.', '', '', '', '', ''),
(30, 0, -6445.390, 578.852, 386.218, 2.3078, 1, 'Perception', 14, '', '', 9001030, 10, 600, 0, 1, '', 'Ashes in a hollow out of the wind, with a log rolled up to sit on.', 'Something is tucked into the split end of the log.', '', '', 'A mountaineer''s flint-and-steel in a tin, and a scrap of map torn along its folds. Pieced back together: Coldridge''s ridges drawn in charcoal, with the trogg caves ringed. The coins wrapped inside it are the more useful part.', '', 'slide', '', ''),
(31, 0, -6346.380, 184.912, 395.670, 5.4856, 0, 'Arcana', 13, '', '', 9001031, 10, 1800, 0, 1, '', '', '', 'Old dwarven surveyors used rings of frost-crystal like this as sounding-stones: set true, the chord carries for miles. As the last stone settles into the root''s voice, the frost around their foot cracks and falls away from a little stone box - a surveyor''s wages, never collected.', 'The crystals moan off-key, and whatever they were set to guard stays shut.', '', '', 'tune', '', ''),
(32, 0, -6190.240, 786.846, 396.064, 3.9754, 1, 'Perception', 13, '', '', 9001032, 10, 1500, 0, 1, 'bard_air', 'Crystals growing out of a frost-split boulder, humming faintly when the wind catches them.', 'One cluster has been chipped by a tool - and the boulder beneath it sounds hollow.', '', '', 'Tuned true, the stones ring together and a hairline seam in the boulder shivers open: someone''s hiding place. Inside, wrapped in felt, a silver tuning fork, a purse of coins, and a scrap of staff paper with four notes inked on it and a line beneath: ''the old ward-stones still answer to this - try the frosted one.'' A bard was here. You hum the four notes until you have them by heart.', '', 'tune', '', ''),
(101, 0, -6122.960, 79.165, 416.991, 6.1486, 1, 'Perception', 12, '', '', 9001101, 10, 800, 0, 1, 'signet', 'Gnawed bones and a trampled trogg nest, long abandoned.', 'Something metal is trodden into the floor of the nest.', '', '', 'A mountaineer''s signet ring, stamped with the Ironforge seal and a name: Thalgrim Coppervein. Kin of the prospector back in Coldridge, maybe - he never mentioned anyone missing.', '', '', '', ''),
(102, 0, -5073.020, 436.788, 410.832, 3.1416, 0, 'Investigation', 13, '', 'Gnome', 9001102, 10, 2500, 1180, 1, '', '', '', 'A gnomish toolbox with a lettered clasp, the name ''Bink'' etched into the lid. Under the wrenches: a radiation badge gone dark, and a letter - ''...if anyone finds this, tell the others I made it out of Gnomeregan. Mostly.'' A few coins are sewn into the lining.', 'Wrenches, gears and a sharp chemical smell. Nothing you can make sense of.', ' Tucked in with it: a Scroll of Bless.', 'Gnomish shorthand - you read it like your own mother''s handwriting.', 'cipher', '', ''),
(103, 0, -5160.540, 692.712, 363.206, 1.4938, 1, 'Perception', 14, '', '', 9001103, 10, 0, 0, 1, 'fimble', 'A low heap of stones and snow, too neat to be natural, marked with a bent spanner.', 'Poking out of the snow at the edge of the heap: the corner of a leather journal.', '', '', 'A journal, the last pages in a shaking hand: ''Day forty outside. The others don''t remember their names any more. I write mine every morning so I won''t forget. Fimble. Fimble. Fimble.''', '', 'dig', '', ''),
(104, 0, -5599.900, 647.107, 384.562, 1.5882, 0, 'Sleight of Hand', 14, '', '', 9001104, 10, 1800, 118, 1, '', '', '', 'The lock is troll-work, crude but clever - knucklebones for tumblers. It clicks. Inside, wrapped in hide: a little red vial and a handful of coins the Frostmane took off travellers.', 'The lock bites back: a bone needle hidden in the hasp jabs your thumb. Whatever''s inside, the trolls can keep it.', '', '', 'lock', '', ''),
(105, 0, -5722.070, 487.089, 394.889, 2.4611, 1, 'Perception', 15, '', '', 9001105, 10, 0, 0, 1, 'frostmane_map', 'A ring of troll skulls on stakes, their eye sockets packed with frost.', 'Something is tucked inside one of the skulls.', '', '', 'A map painted on hide, cut into squares and laid back crooked. Turned right, it shows the Frostmane caves, and a chieftain''s mark at the deepest point. Whoever leads the Frostmane, this is where they sleep.', '', 'mosaic', '', ''),
(106, 0, -5071.550, -292.779, 442.039, 2.6355, 0, 'Nature', 13, '', '', 9001106, 10, 1200, 0, 1, 'shimmerweed', '', '', 'Around the cold fire, bundles of a pale blue weed hang drying on sticks. Shimmerweed - the Frostmane seers chew it before a vision. You take the cleanest bundle; an alchemist would pay well for it.', 'Bundles of some pale weed drying by the fire. Medicine, poison or dinner - you couldn''t say.', '', '', '', '', ''),
(107, 0, -5479.810, -217.343, 354.253, 3.1416, 0, 'Medicine', 14, '', '', 9001107, 10, 2000, 955, 1, 'neat_wound', '', '', 'A dwarf hunter, picked over by wendigos - but not killed by them. The wound in his neck is too small and too neat. Something else got him first; the wendigos only found him after. His pouch is still on his belt, and in it his field book: thirty years of tracks, weather-signs and snow-craft in a tiny, careful hand. It reads like sitting by his fire.', 'Bones and torn leather. The wendigos have been at him; there isn''t much left to read.', ' Tucked in with it: a Scroll of Cure Wounds.', '', '', '', 'Survival'),
(108, 0, -5716.870, -162.426, 374.256, 3.0892, 1, 'Perception', 15, '', '', 9001108, 10, 0, 12259, 1, 'sleeps_by_day', 'A heavy wooden locker, claw-scored and stinking of old meat.', 'Behind the locker, wedged deep against the rock, a glint of steel.', '', '', 'A skinning knife with a Stormpike crest on the pommel, dropped by someone leaving in a great hurry - and no ordinary knife: the edge takes the light like water, and it has not a speck of rust on it. A note is wound round the handle: ''Whoever finds this - the beast sleeps by day. GO BY DAY.''', '', '', '', ''),
(109, 0, -5385.780, -60.988, 393.626, 3.6128, 0, 'Survival', 14, '', '', 9001109, 10, 1500, 0, 1, 'lame_beast', '', '', 'Huge splayed prints circle the heaped stones and lead off toward the caves - something far bigger than a wolf, on two legs, dragging its left foot. Under the snow: the remains of its last kill, and a hunter''s pouch it had no use for.', 'Prints everywhere, crossing and re-crossing - wolf, boar, something bigger. You lose the thread.', '', '', 'tracks', '', ''),
(110, 0, -5834.260, -1493.210, 359.328, -1.8675, 0, 'Athletics', 11, '', '', 9001110, 10, 3000, 2569, 1, '', '', '', 'You heave the overturned ore cart back onto its wheels. Beneath it, pressed flat into the snow, a miner''s pack: fur-lined boots that never seem to sink in the snow, a candle stub, and his last week''s pay.', 'The cart doesn''t budge. Whatever''s under it is staying there.', '', '', '', '', ''),
(111, 0, -5586.130, -1741.280, 371.757, -0.1222, 1, 'Perception', 14, '', '', 9001111, 10, 500, 0, 1, 'songbird', 'A trogg trophy pile: helmets, boots and a dented shield, all heaped together.', 'One of the helmets rattles when the wind catches it.', '', '', 'Inside the dented helmet, a little brass box - and in it a clockwork songbird that still sings when you wind it: four notes, over and over, the first bar of an old Bronzebeard marching air. Someone made this for a child. By the third winding you could whistle it in your sleep.', '', '', '', ''),
(112, 0, -5422.980, -1276.980, 447.711, 4.5030, 0, 'History', 13, '', 'Dwarf', 9001112, 10, 4000, 0, 1, 'beast_below', '', '', 'Miners'' marks, centuries old: a hammer, a crossed-out eye, and the rune that means ''beast below''. The old miners knew what slept under this mountain - and that it could barely see. Under the stone they left an offering for luck: coins gone green with age.', 'Scratches and old marks. Miners'' doodles, probably.', '', 'Your grandfather taught you these marks before you could hold a pick.', 'runes', '', ''),
(113, 0, -5406.120, 516.121, 386.359, 1.9024, 0, 'Nature', 10, '', '', 9001113, 10, 0, 118, 1, '', '', '', 'A herbalist''s camp, abandoned: drying racks and a broken mortar. Her last batch is still on the rack, half bottled, the measures scratched on the vials. You finish pouring it to her marks - peacebloom and silverleaf, by the smell.', 'Dead leaves and a broken mortar. Whatever grew here, it''s all brown now.', '', '', 'pour', '', ''),
(114, 0, -5746.870, -371.430, 365.881, 1.2392, 1, 'Perception', 12, '', '', 9001114, 10, 900, 0, 1, '', 'Frost-crystals have grown right over an old mountaineer ammo crate, and they hum when the wind rises.', 'The crate''s lid is frozen shut under the crystals - but the hum changes when you lean on it.', '', '', 'Set ringing together, the crystals shiver the ice off the lid in one sheet. Inside, in a nest of wadding: a powder horn engraved ''For Hegnar, from the lads at Steelgrill''s''. Empty now, but beautifully made - and worth a round of drinks to the right dwarf.', '', 'tune', '', ''),
(115, 0, -5815.590, -1697.700, 359.554, 1.0647, 0, 'Sleight of Hand', 13, '', '', 9001115, 10, 2500, 118, 1, '', '', '', 'A miner''s strongbox with a dial: trogg-proof, he thought, but not you-proof. Inside, his savings and a sealed red vial.', 'The lock jams, and a trogg somewhere below hoots at the noise. Best leave it.', '', '', 'dial', '', ''),
(116, 0, -5493.270, -341.810, 354.891, 1.7977, 1, 'Perception', 14, '', '', 9001116, 10, 1500, 0, 1, '', 'The scattered leavings of a wendigo''s meal.', 'Among the bones, a glint of metal - a ring, still on a finger.', '', '', 'A plain silver band engraved inside: ''To Brann, from Hilda. Come home safe.'' You take it, meaning to find Hilda one day.', '', '', '', ''),
(117, 0, -5403.610, -769.998, 395.009, 4.3335, 0, 'Religion', 13, '', '', 9001117, 10, 1800, 0, 1, '', '', '', 'Three low cairns, each marked with the hammer of the Explorers - the last one tumbled by the wind. You build it up again, stone on stone, and say the old words over them. The cold seems to ease a little, and at the foot of the last cairn you find an offering left by a mourner long ago - coins, for the ferryman.', 'Three low cairns in the snow. You stand a while, but whoever lies here stays silent.', '', '', 'stack', '', ''),
(118, 0, -4990.840, -58.100, 386.758, 2.8871, 1, 'Perception', 13, '', '', 9001118, 10, 0, 118, 1, '', 'A block of ice where meltwater pooled and froze - with the splintered corner of a supply crate sticking out of it. A bear dragged it this far and gave up.', 'Something wrapped in waxed cloth is frozen in beside the crate.', '', '', 'Two hard biscuits and a healing draught in waxed cloth - an Ironforge quartermaster''s seal on the wrap, and not a drop spoiled.', '', 'ice', '', ''),
(119, 0, -5006.480, 207.108, 389.101, 0.2587, 0, 'Investigation', 13, '', '', 9001119, 10, 2200, 0, 1, '', '', '', 'The cart was carrying ore to Ironforge when something big stopped it. Under the seat, a drawer nailed shut: the carter''s purse and a bill of lading signed by a very angry foreman.', 'A wrecked cart. Whatever was worth having went with whoever got away.', '', '', 'pry', '', ''),
(120, 0, -5176.930, 357.412, 395.839, 4.4411, 1, 'Perception', 15, '', '', 9001120, 10, 3000, 0, 1, '', 'A snow leopard''s den, strewn with the bones of its prey.', 'Deep in the den, something that isn''t bone.', '', '', 'A gnomish pocket-watch, still ticking, with ''GNOMEREGAN - PROPERTY OF THE TINKERS'' COUNCIL'' stamped on the back, and a fat purse the same unlucky gnome was carrying. The leopard must have liked how they shone.', '', '', '', ''),
(121, 0, -5676.780, 658.393, 387.589, 6.2526, 0, 'Investigation', 12, '', '', 9001121, 10, 0, 0, 1, 'salt', '', '', 'A Frostmane supply cache: furs, bones - and a heavy pouch of grey rock salt, wrapped with great care. The trolls must value it. You take the salt.', 'Furs and bones. Nothing you''d want to carry.', '', '', '', '', ''),
(122, 0, -5441.790, 108.379, 396.552, 2.4437, 0, 'Survival', 13, '', '', 9001122, 10, 1500, 20906, 1, '', '', '', 'Somebody buried a cache here and marked it with three stones in a line. Under the snow: a hunter''s spare kit and a little money.', 'Snow, rocks and more snow.', '', '', 'dig', '', ''),
(123, 0, -5350.680, -351.551, 395.694, 2.6387, 1, 'Perception', 11, '', '', 9001123, 10, 0, 21934, 1, '', 'A hunters'' camp, long cold. A black bear has been nosing round it.', 'Hanging high in a tree, out of the bear''s reach: a bundle.', '', '', 'A smooth stone on a cord, rubbed bright by a prospector''s thumb, wrapped in cloth - and a note: ''For whoever comes after. It always got me moving first.''', '', '', '', ''),
(124, 0, -5532.740, -1050.600, 392.146, 0.2590, 0, 'Medicine', 13, '', '', 9001124, 10, 2000, 118, 1, '', '', '', 'A ram, brought down by something that bit clean through its leg. Whatever it was, it''s long gone - but the rider''s saddlebag is still strapped to the carcass.', 'A dead ram. You can''t tell much more than that.', '', '', '', '', ''),
(125, 0, -5819.540, -1283.800, 382.774, 4.7041, 0, 'History', 14, '', 'Dwarf', 9001125, 10, 3500, 858, 1, '', '', '', 'An old boundary stone from the Three Hammers days, carved with the clan marks of the Bronzebeards - and under them, a row of four small holes, like a flute''s. A singing-lock. The soldiers who hid things behind stones like this opened them with a marching air.', 'An old stone with old carvings, too worn to read.', '', 'Bronzebeard marks - every dwarf child knows them. The tune is another matter.', 'song', 'songbird', ''),
(126, 0, -5660.260, 178.374, 427.587, 0.6458, 1, 'Perception', 14, '', '', 9001126, 10, 1800, 0, 1, '', 'An abandoned prospector''s barrow, tipped on its side, its ore spilled in the snow.', 'One lump of the spilled ore is the wrong shape - round, knobbly, and far too heavy.', '', '', 'Not ore at all: a geode, packed with smoky crystal. The prospector never knew what he''d dug up. Under it lies the purse he dropped in his hurry, and a scrap of map with a seam marked on it.', '', 'geode', '', ''),
(127, 0, -5965.870, 29.531, 372.507, 6.2134, 0, 'Nature', 12, '', '', 9001127, 10, 0, 0, 1, 'honeycomb', '', '', 'Bees have made a hive in the hollow of a dead tree beside the old fire. You smoke them sleepy with the embers and help yourself to a dripping honeycomb.', 'Something buzzes angrily in the dead tree. You decide you don''t want to know what.', '', '', 'smoke', '', ''),
(128, 0, -4925.730, 670.234, 249.495, 2.7333, 1, 'Perception', 14, '', '', 9001128, 10, 800, 0, 1, '', 'A gnomish crate, its lid blown off from the inside.', 'Inside, a gnomish puzzle-tray: a marble, a field of holes, and something tiny whirring in the locked compartment at the end.', '', '', 'A clockwork beetle, the size of your thumb, that walks in circles and then sits up and beeps. Utterly useless, utterly delightful.', '', 'maze', '', ''),
(201, 0, -5277.470, -2694.250, 344.979, 2.5656, 1, 'Perception', 12, '', '', 9001201, 10, 1500, 0, 1, '', 'A spill of broken stone the troggs dragged out of their diggings and left.', 'One stone among them is too round, and rings when you knock it.', '', '', 'A geode the troggs threw away with the rubble - they wanted the shiny seam, and never thought to look inside a dull rock. The crystal is the colour of the loch at evening.', '', 'geode', '', ''),
(202, 0, -4876.230, -3318.480, 305.601, -2.8100, 0, 'Investigation', 13, '', '', 9001202, 10, 2500, 1181, 1, '', '', '', 'A Miners'' League supply drop that never got collected. Under the picks and lamp oil, a paymaster''s pouch - the miners'' wages for a month that never came.', 'Picks, lamp oil and mouldy hardtack. Nothing you''d want.', ' Tucked in with it: a Scroll of Sleep.', '', '', '', ''),
(203, 0, -4967.330, -3007.320, 318.483, 0.9250, 0, 'Sleight of Hand', 14, '', '', 9001203, 10, 1500, 0, 1, 'candle', '', '', 'The lock gives. The Miners'' League keeps its candles here - fat white tallow ones, a whole box - and a little money for the next order. You take a candle and the coins.', 'The lock won''t budge, and something inside rattles mockingly.', '', '', 'lock', '', ''),
(204, 0, -4754.940, -4120.300, 310.981, -0.0175, 0, 'Athletics', 13, '', '', 9001204, 10, 4000, 4368, 1, '', '', '', 'You lever the nails out of the rusted lid. Ogres have been using it as a strongbox: a mess of stolen coins, a gnawed boot, and a pair of tunneller''s lenses, not even scratched.', 'The lid is rusted shut, and heaving on it only bruises your fingers.', '', '', 'pry', '', ''),
(205, 0, -4717.310, -3088.100, 306.458, 3.0019, 0, 'History', 13, '', 'Dwarf', 9001205, 10, 3500, 3012, 1, '', '', '', 'A Khaz Modan puzzle-lock: lettered rings geared each to the next, and the word they want stamped on the hasp. It opens on a surveyor''s savings.', 'A ring-lock with old dwarven numerals. Whatever date it wants, you don''t know it.', ' Tucked in with it: a Scroll of Misty Step.', 'Every dwarf child learns when Thelsamar was founded.', 'cipher', '', ''),
(206, 0, -5692.800, -3912.190, 337.257, 1.6755, 1, 'Perception', 14, '', '', 9001206, 10, 0, 858, 1, '', 'A crate half sunk into the ferns, its stencil long faded.', 'The faded stencil reads ''Chirurgeon - handle with care''.', '', '', 'A potion of greater healing, packed in straw. Someone in Thelsamar is still waiting for this.', '', '', '', ''),
(207, 0, -5932.270, -3719.540, 342.366, 6.0171, 0, 'Survival', 14, '', '', 9001207, 10, 2200, 0, 1, '', '', '', 'Huge claw marks, and the remains of a hunter who followed them too far. His pack is intact: arrows, jerky, his last bounty - and his bestiary, every creature of the loch drawn from life with its habits written round it. He knew them all. Now so do you.', 'Old bones and older claw marks. You don''t like this place.', '', '', 'tracks', '', 'Nature'),
(208, 0, -5830.150, -3346.600, 299.772, 0.8461, 1, 'Perception', 14, '', '', 9001208, 10, 3000, 0, 1, '', 'Bones wrapped in old grey silk, hanging from the rocks.', 'One of the silk bundles is the wrong shape - square, like a purse.', '', '', 'An adventurer''s purse, cocooned with its owner - a heavy one. You pick the silk loose strand by strand and try not to look too closely at the rest.', '', 'knots', '', ''),
(209, 0, -5521.670, -3489.780, 298.831, 4.1547, 0, 'Medicine', 13, '', '', 9001209, 10, 1200, 118, 1, '', '', '', 'A fisherman, taken by a crocolisk - the teeth marks say so. His rod is still wedged in the rocks, the line out in the water and something heavy on it. You haul it in: his tackle bag, snagged on the hook - a few coins and a healing draught he never had time to drink.', 'Bones on the shore. The loch keeps its secrets.', '', '', 'fish', '', ''),
(210, 0, -4711.650, -2745.290, 325.609, 0.6593, 0, 'Animal Handling', 12, '', '', 9001210, 10, 1500, 0, 1, 'wayfarer_tune', '', '', 'A ram is tethered by the dead fire, starving and frightened. You calm it and lead it back to the road, where a grateful herder finds you, presses coins into your hand, and walks you a mile on your way - whistling the same four-note wayfarers'' tune the whole time. ''Hum that at the old road-shrines,'' he says. ''They like it.''', 'A tethered ram that butts at you every time you come near. Best leave it.', '', '', '', '', ''),
(211, 0, -5659.120, -4178.310, 391.667, 3.2374, 1, 'Perception', 13, '', '', 9001211, 10, 1000, 0, 1, '', 'A scatter of picked bones under a buzzard roost.', 'Something glints up in the roost among the droppings - buzzards like shiny things too.', '', '', 'A handful of coins and a silver button, pecked clean. Disgusting, but money is money.', '', 'climb', '', ''),
(212, 0, -4792.080, -3581.650, 306.592, 2.0249, 0, 'Investigation', 14, '', '', 9001212, 10, 0, 0, 1, 'dam_orders', '', '', 'Dark Iron supplies, the lid wired to the powder kegs - a trap. Past it, under the kegs, a sealed order in the cramped Dark Iron script: charges on the dam, to be set before the next moon. You take it. The Mountaineers will want to see this.', 'Black powder, fuse cord and Dark Iron rations. Nothing you understand, and nothing you want near a fire.', '', '', 'wire', '', ''),
(213, 0, -5716.180, -3110.810, 316.787, 3.0654, 0, 'Nature', 11, '', '', 9001213, 10, 600, 7108, 1, '', '', '', 'These aren''t a bear''s leavings - they''re a bear''s larder. Beside it, a hollow tree hums with bees, and with a smoking brand held to them, the old honey in the lowest comb is yours.', 'Bones and buzzing. You decide not to investigate the buzzing.', '', '', 'smoke', '', ''),
(214, 0, -5453.850, -3119.810, 348.770, 0.9226, 1, 'Perception', 11, '', '', 9001214, 10, 800, 118, 1, '', 'A hunters'' camp, long cold, the bedrolls clawed to ribbons.', 'A pack was hung in a tree, out of reach of whatever came through.', '', '', 'The hunters'' spare kit: a healing draught and a little money for the road.', '', '', '', ''),
(215, 0, -5917.780, -3007.370, 378.085, 5.2927, 0, 'Arcana', 15, '', '', 9001215, 10, 2000, 1116, 1, '', '', '', 'A trogg totem of stacked skulls, humming at a pitch that makes your teeth ache. The hum comes from three raw crystals pressed into the eye sockets, each a little off from the others - a seer''s ward, badly made. Bring them into tune and it will have nothing left to hold on to.', 'Skulls, stacked with care, humming at a pitch that makes your teeth ache.', '', '', 'tune', '', ''),
(216, 0, -5875.740, -2516.050, 307.355, 5.9968, 1, 'Perception', 13, '', '', 9001216, 10, 1800, 0, 1, '', 'An overturned cart by the road, its wheel smashed.', 'The cart has a false bottom - under a jumble of spilled crates that will have to be slid aside.', '', '', 'A smuggler''s stash: coins, and nothing at all to say whose.', '', 'crates', '', ''),
(217, 0, -5709.460, -3251.340, 313.201, 3.3990, 0, 'Religion', 13, '', '', 9001217, 10, 2400, 858, 1, '', '', '', 'Stones arranged round the fire-pit in the old Khaz Modan way - a wayfarer''s shrine, and the keystone is a singing-stone, worn smooth where a thousand travellers have laid a hand on it and hummed. It wants its tune: four notes.', 'A ring of stones round a dead fire. If it means something, it isn''t to you.', '', '', 'song', 'wayfarer_tune', ''),
(218, 0, -5016.720, -4019.240, 301.257, 5.5199, 1, 'Perception', 14, '', '', 9001218, 10, 0, 0, 1, 'ogre_toll', 'A heap of skulls and junk outside an ogre camp - their idea of decoration.', 'A sack is stuffed under the heap, bulging with something.', '', '', 'A sack of polished river stones and glittering mica - an ogre''s idea of treasure. Worthless to you, but you can think of someone who might be impressed.', '', '', '', ''),
(301, 0, -3463.880, -1015.160, 7.500, 3.0300, 0, 'Survival', 11, '', '', 9001301, 10, 0, 22992, 1, 'smoked_fish', '', '', 'A fisherman''s smoke-rack over a dead fire, abandoned in a hurry - crocolisk tracks say why. The top rack is out of their reach - and yours. A few well-aimed stones bring it down, and the fish on it are done to a turn: a whole basket of them, smoked hard and sweet. Anything with a nose would follow this for a mile.', 'A dead fire and some sticks lashed together. Whatever hung here, something ate it.', '', '', 'sling', '', ''),
(302, 0, -3920.280, -1053.160, 28.377, 2.7053, 0, 'Investigation', 12, '', '', 9001302, 10, 3000, 1477, 1, 'war_writ', '', '', 'A Menethil supply wagon, axle snapped, stripped of everything a raider could carry. They missed the driver''s seat-box: a purse, and a sealed dispatch for the harbour garrison - ''Three companies of riflemen march from Dun Algaz. Hold the road until they come.'' The seal is Ironforge''s, and unbroken.', 'A wrecked wagon, picked clean. Even the horseshoes are gone.', ' Tucked in with it: a Scroll of Web.', '', '', '', ''),
(303, 0, -3594.020, -1207.030, 11.646, 1.6856, 0, 'Nature', 12, '', '', 9001303, 10, 2200, 0, 1, '', '', '', 'A raptor''s nest-scrape, long abandoned: shell fragments, and the bones of everything the brood was fed. Raptors bring their young whatever glitters, to teach them to snatch. Sifted out from under the shells: a traveller''s rings and buckles, pecked bright.', 'Bones and bits of shell. Something nested here once. You''d rather not meet it.', '', '', 'sift', '', ''),
(304, 0, -3644.190, -1439.960, 11.714, 0.0349, 1, 'Perception', 13, '', '', 9001304, 10, 2600, 0, 1, '', 'A spill of round stones at the foot of a bank, furred green with moss.', 'One stone has no moss on it at all - and the rain runs off it as if it were glass.', '', '', 'A geode, washed out of the bank in the last flood. Inside, bands of green and white agate round a hollow full of little clear points. A jeweller in Menethil would not haggle long.', '', 'geode', '', ''),
(305, 0, -3586.790, -1894.770, 99.064, 2.7925, 0, 'History', 14, '', 'Dwarf', 9001305, 10, 4000, 4426, 1, '', '', '', 'A dig-marker of the Explorers'' League, older than the excavation below it: ''First trench. Nothing found. Pay chest buried against thieves - W.'' Prospector Whelgar has clearly forgotten where he put his own wages.', 'A carved stone, green with age. It marks something. You can''t tell what.', ' Tucked in with it: a Scroll of Blindness.', 'League trench-marks. You could read these in the dark.', 'runes', '', ''),
(306, 0, -3308.060, -1899.060, 31.736, -2.1119, 0, 'Survival', 13, '', '', 9001306, 10, 1500, 0, 1, 'great_bone', '', '', 'The soil here has been turned, and not by a spade - by rain, year after year, washing down off the dig above. Something long and pale shows through. You clear it, and keep clearing: a thighbone, from a raptor that must have stood taller than a house. It is longer than you are. You take it anyway.', 'Loose soil, roots and worms. If there''s anything under it, it''s a long way down.', '', '', 'dig', '', ''),
(307, 0, -3221.880, -1647.430, 8.588, 5.1416, 1, 'Perception', 12, '', '', 9001307, 10, 0, 118, 2, '', 'A crate half sunk in the mud at the edge of a channel, tilted like a foundering ship.', 'The crate''s lower half lies under the channel water - and something inside clinks.', '', '', 'Two healing draughts, packed in reeds, and the stencil of a Menethil apothecary. The upper half of the crate held more. The crocolisks did not appreciate them.', '', 'dive', '', ''),
(308, 0, -3187.430, -1176.530, 7.971, 0.7854, 0, 'Sleight of Hand', 14, '', '', 9001308, 10, 1800, 0, 1, 'shanty', '', '', 'A sailor''s footlocker, washed up whole. The lock is salt-eaten solid, but the hasp is only nailed on, and nails come out. Inside: a tarred jacket, a purse, and a little brass music-box with a ship engraved on the lid. Wound, it plays four notes of a shanty, over and over, a bit flat. You find yourself humming it. On the bottom someone has scratched: ''The old sea-stone up the shore knows this one.''', 'The lock is one lump of rust and salt. Your pick doesn''t even find the keyhole.', '', '', 'pry', '', ''),
(309, 0, -2953.410, -1020.380, 10.009, 3.9159, 1, 'Perception', 14, '', '', 9001309, 10, 0, 0, 1, 'ships_bell', 'Wreckage above the tide line: a stove-in ship''s boat, half full of sand.', 'Something curved and green-brown is pinned under the boat''s broken timbers - metal, not wood.', '', '', 'A ship''s bell, bronze, the size of your head. The clapper is still in it. Round the rim, through the verdigris: INTREPID. You ring it once, without meaning to, and out on the wreck something seems to turn and listen.', '', 'sticks', '', ''),
(310, 0, -3053.710, -1153.920, 9.152, 3.0368, 0, 'Arcana', 13, '', '', 9001310, 10, 1500, 1190, 1, '', '', '', 'A standing stone drilled through with four holes, set where the wind comes off the sea. The tide-folk who raised it are long gone, but the charm in it is not: sing it the air it was made for, and it will give back what was left in its keeping.', 'An old stone with holes in it. The wind makes it moan. That''s all.', '', '', 'song', 'shanty', ''),
(311, 0, -3307.770, -1236.440, 6.436, 4.8599, 0, 'Religion', 11, '', '', 9001311, 10, 1400, 0, 1, '', '', '', 'A murloc shrine: fish skulls on reeds, arranged with real care round a flat stone. They leave their god shiny things. You say something polite to whatever is listening and take only the coins - murlocs have no use for those. The pretty shells you leave.', 'Fish heads on sticks. It smells exactly as you''d expect.', '', '', '', '', ''),
(312, 0, -3046.680, -1545.770, 3.870, 5.0338, 1, 'Perception', 13, '', '', 9001312, 10, 2800, 0, 1, '', 'Pale crystals growing from a drowned log, each with a marsh-light flickering inside it.', 'The lights pulse out of step with each other - and the log under them is hollow.', '', '', 'Brought into tune, the three lights steady and burn as one, bright enough to read by, and the rotten end of the log falls away. A smuggler''s cache: oilcloth, and inside it more coin than a smuggler ought to leave lying about.', '', 'tune', '', ''),
(313, 0, -4355.330, -2421.200, 228.484, 1.0482, 0, 'Investigation', 13, '', '', 9001313, 10, 800, 0, 1, 'dragonmaw_orders', '', '', 'A cold camp just off the tunnel road: one bedroll, one set of orc boot-prints, and a courier''s satchel left under a rock. Inside, orders on hide, cut into squares the way couriers carry them. Turned right and laid together, in a clerk''s Orcish: ''To the warden of the pass. Report to the high camp. You are late.'' - and at the bottom, a chieftain''s mark pressed in red clay.', 'A dead fire and a bedroll. Someone camped here alone. Nothing says who.', '', '', 'mosaic', '', ''),
(314, 0, -3904.010, -2892.130, 9.995, 4.7769, 1, 'Perception', 13, '', '', 9001314, 10, 1600, 118, 1, '', 'A trapper''s hand-sledge, overturned among the reeds, its load of pelts long since dragged off.', 'The sledge has a false runner, hollow, lashed shut with a hopeless tangle of rawhide.', '', '', 'The trapper''s savings, rolled in a strip of fur and pushed up inside the runner, and a healing draught wedged in after them. He never came back for either.', '', 'knots', '', ''),
(315, 0, -3804.330, -3087.270, 12.287, 4.8869, 0, 'Investigation', 14, '', '', 9001315, 10, 700, 0, 1, '', '', '', 'A card-sharp''s camp, by the look of it: a folding table and a marked deck in a dry tin. Match the marks and the cards pair off - and under the last pair, in the tin''s false bottom, a ledger. Not of money - of people. Every mark he ever fleeced, and how he knew they were lying: the eyes, the hands, the breath. Forty years of watching faces. By the last page you are watching your own.', 'A dead fire, a broken table, some pulped playing cards. A gambler down on his luck.', '', '', 'pairs', '', 'Insight'),
(316, 0, -3766.710, -2700.050, 38.334, 4.2412, 0, 'Nature', 12, '', '', 9001316, 10, 2400, 0, 1, '', '', '', 'Bog-iron country: the stones here weep rust. But one of them is too light for its size and rattles when you shake it. Cracked open, it''s hollow, and lined with something black and glittering that a smith would call hematite and pay for by the ounce.', 'Rusty stones in a rusty puddle.', '', '', 'geode', '', ''),
(317, 0, -3452.640, -2503.420, 32.961, 4.5565, 0, 'Medicine', 13, '', '', 9001317, 10, 900, 0, 1, '', '', '', 'An orc, dead of fever, not wounds - he lay down here and didn''t get up. No clan marks: he cut them off. A deserter. Sewn into his jerkin is the route he used to slip the Dragonmaw pickets, drawn step by step: where to put your feet, when to breathe, how to cross open ground between two sentries. It is the work of a careful, frightened man, and it is very good.', 'A dead orc, some weeks gone. You don''t look closer than you have to.', '', '', '', '', 'Stealth'),
(318, 0, -3618.660, -3112.000, 22.930, 6.1360, 1, 'Perception', 15, '', '', 9001318, 10, 3500, 858, 1, '', 'A cairn of charred skulls on a rise - a Dragonmaw offering to the red dragons, the stones still warm.', 'The offering bowl at the foot of the cairn has a second bowl beneath it.', '', '', 'What the Dragonmaw give the dragons: gold, mostly, a good deal of it, half-melted into lumps - and tucked among them a healer''s flask of the strong stuff, which they must have taken off someone who needed it less than you do.', '', '', '', ''),
(319, 0, -2917.710, -1810.560, 8.509, 4.6077, 0, 'Investigation', 13, '', '', 9001319, 10, 0, 0, 1, 'gnoll_totem', '', '', 'A Mosshide boundary-pole: skulls, feathers, and at the top a totem carved from one piece of black wood - a gnoll''s head with real teeth set in it. Every pack has one. Whoever carries it speaks for the Alpha, and the gnolls who lose theirs are too ashamed to say so. It comes off the pole with a twist.', 'Skulls on a pole. A warning. You take the hint.', '', '', '', '', ''),
(320, 0, -3108.520, -2190.420, 9.296, -1.8675, 0, 'Sleight of Hand', 15, '', '', 9001320, 10, 0, 935, 1, '', '', '', 'An iron-bound chest sunk to its lid in the mud, with a watch-captain''s seal on the hasp and a lock to match. It fights you every pin of the way. Inside, wrapped in a Menethil tabard: a short sword of blued steel, light as a reed, with a night-watchman''s lantern etched on the blade. It has kept its edge in a bog. It will keep it anywhere.', 'A serious lock, made by someone serious. It keeps your pick as a souvenir.', '', '', 'lock', '', ''),
(321, 0, -2902.530, -2053.890, 9.195, 0.8552, 0, 'Athletics', 11, '', '', 9001321, 10, 1000, 2899, 1, '', '', '', 'A barrel, bung-up in the mud, far too heavy to be empty. You rock it loose and roll it to dry ground. Melon juice - a whole barrel, still sweet, lost off some trader''s raft. You drink what you can, and find the trader''s purse nailed inside the lid for safe keeping - wrapped in a belt of shaggy white hide.', 'The barrel is stuck fast, and all your heaving does is sink you to the knees.', '', '', '', '', ''),
(322, 0, -2782.350, -2867.910, 40.171, 3.9821, 0, 'Sleight of Hand', 13, '', '', 9001322, 10, 2000, 0, 1, 'forge_seal', '', '', 'A Dark Iron strongbox, soot-black, the lid a nasty little thing with a spring-trap in it. You thread past the trigger, and it gives. Inside: pay for a work-gang, and an overseer''s forge-seal on a chain - the stamp that says the bearer''s word is the forge''s word. No Dark Iron below an overseer would dare question it.', 'The spring in the lock snaps shut on your pick and very nearly on your finger.', '', '', 'wire', '', ''),
(323, 0, -2955.900, -2152.340, 17.383, 6.1610, 0, 'Arcana', 13, '', '', 9001323, 10, 2500, 0, 1, '', '', '', 'A warding-stone at the edge of the old tombs, set to keep the slimes off the dead. The ward still works; it''s the offering-niche behind it that interests you. Quench the ward''s glyphs, every one, and it opens: grave-goods someone left for a dwarf they loved.', 'Old carvings under the moss. They feel like they''re waiting for something.', '', '', 'wards', '', ''),
(324, 0, -2791.770, -2558.890, 63.457, 5.8124, 0, 'Survival', 12, '', '', 9001324, 10, 1200, 0, 1, '', '', '', 'A raptor kill, a few days old: a pack-mule, and not much left of it. The pack went one way and the mule the other. You follow the drag-marks to a thorn bush where the saddlebags snagged - and the raptors, having no use for coin, left them hanging.', 'Bones, and big three-toed prints all round them. You don''t linger.', '', '', 'tracks', '', ''),
(325, 0, -2816.660, -1908.050, 15.472, 6.2134, 1, 'Perception', 14, '', '', 9001325, 10, 2200, 118, 1, '', 'A heap of mossy stones on a hummock, the only dry ground for a hundred paces.', 'The moss on one side has been lifted like a rug and laid back - and not long ago.', '', '', 'Under the turf, a prospector''s cache: a pick, a bag of tin-stone, and a pan of gravel he never finished washing - and at the bottom of it, once you have, his purse and a healing draught, wrapped against the wet.', '', 'pan', '', ''),
(326, 0, -2769.880, -1469.990, 7.035, 0.7826, 1, 'Perception', 11, '', '', 9001326, 10, 500, 6543, 1, '', 'A fish-crate caught in the roots of a drowned tree, bleached grey.', 'A line runs from it down into the black water, and something is on the end of it.', '', '', 'A fisherman''s bundle, never collected: the few coins he kept, and a pair of bracers stitched from fen-reed and leather, tougher than they look.', '', 'fish', '', ''),
(401, 0, -2111.990, -2595.170, 83.496, 4.6537, 0, 'Survival', 11, '', '', 9001401, 10, 1400, 0, 1, '', '', '', 'A strider''s carcass, brought down and left half eaten - by something that kills for sport. The rider''s saddlebag lies trampled in the grass a little way off. The strider''s owner, wisely, ran.', 'Long bones and a great deal of feathers. Something big fed here, and might come back.', '', '', 'tracks', '', ''),
(402, 0, -2102.870, -2828.600, 79.017, 3.3859, 1, 'Perception', 12, '', '', 9001402, 10, 2800, 1478, 1, '', 'A spill of grey stones at the foot of a crag, green with lichen.', 'One of them is too round, and rings hollow when your boot nudges it.', '', '', 'A geode the size of a loaf, cracked clean in two: violet points inside, packed like teeth. The gem-cutters of Refuge Pointe still pay highland prices. Tucked in with it: a Scroll of Fireball.', '', 'geode', '', ''),
(403, 0, -1731.550, -3372.450, 32.319, 2.5747, 0, 'Religion', 13, '', '', 9001403, 10, 900, 0, 1, 'fetish', '', '', 'A Witherbark shrine: skulls on stakes, painted with red clay, round a hollow stump with a witch doctor''s drum on it. Beat the shrine''s rhythm and the stump''s lid lifts. In the stump, wrapped in a strip of hide, is a fetish of bone and bark and feathers, sticky with old offerings - the mark of the tribe''s witch doctor, left here to draw power from the spirits. Without it, a Witherbark doctor is just a troll in a mask.', 'Painted skulls on stakes. They seem to be looking at you. You''d rather they didn''t.', '', '', 'drum', '', ''),
(404, 0, -1877.380, -2722.490, 56.183, 5.1023, 0, 'Sleight of Hand', 13, '', '', 9001404, 10, 1200, 0, 1, 'tin_crown', '', '', 'An iron-bound strongbox, dented all over where something tried to open it with a rock. The lock is simple, once you''re not an ogre. Inside, among a few coins and a great many pretty pebbles, lies a crown: tin, bent, set with bits of coloured glass - a mummer''s prop from some travelling show. The ogres clearly couldn''t open the box. They clearly very much wanted to.', 'The lock is jammed with grit and ogre spit. It doesn''t budge.', '', '', 'lock', '', ''),
(405, 0, -1935.640, -3158.900, 84.365, 1.5882, 0, 'History', 13, '', 'Human', 9001405, 10, 3200, 10305, 1, '', '', '', 'A mile-stone of the old Arathorian road, the king''s sun on its face. The carved sequence under it isn''t a distance - it''s a muster-cache''s lock, from the Troll Wars. Press the signs in the order the old soldiers learned them, and a stone drawer slides out: a soldier''s last pay, never collected.', 'An old road-stone. The carvings are worn and you can''t make them mean anything.', ' Tucked in with it: a Scroll of Ice Storm.', 'The signs of the old kingdom''s muster. Your grandmother taught you this rhyme.', 'runes', '', ''),
(406, 0, -1808.910, -3075.930, 46.668, 3.5388, 1, 'Perception', 11, '', '', 9001406, 10, 800, 118, 1, '', 'A scatter of bleached bones on a sunny rock, picked spotless by buzzards.', 'Something under the ribcage catches the light.', '', '', 'A traveller''s purse, the leather gone hard as wood, and a healing draught still sealed in wax. The buzzards had no use for either.', '', '', '', ''),
(407, 0, -1756.260, -3523.510, 72.509, 5.0440, 0, 'Investigation', 12, '', '', 9001407, 10, 1100, 3392, 1, '', '', '', 'A hunters'' fire, abandoned in a hurry - the spit still across it, the pot knocked over. Under a flat stone by the ashes, where hunters keep what they don''t want to carry, a twist of cloth with coins in it, and a battered highland warhelm.', 'Ashes and a spit. Whoever cooked here left in a hurry and took everything.', '', '', '', '', ''),
(408, 0, -1709.250, -3219.010, 37.577, 2.4609, 0, 'Survival', 14, '', '', 9001408, 10, 3500, 0, 1, '', '', '', 'A cairn over a shallow grave - and the grave has been dug and filled again, more than once, by someone who kept coming back for what was in it. Under the last layer, a strongbox of a smuggler''s takings, and a note: ''The rest at the Pointe. Tell no one. - J.''', 'Heavy stones on hard ground. You move a few, and stop when your back complains.', '', '', 'dig', '', ''),
(409, 0, -1586.100, -1628.740, 68.723, 5.6011, 0, 'Investigation', 15, '', '', 9001409, 10, 2000, 0, 1, 'trollbane_signet', '', '', 'A noble''s travelling-chest under a heap of fallen beams in the outer ward, its crest scraped off - but not well enough: the Trollbane boar is still there under the scratches. The chest is empty save for a false bottom, and under that a velvet pouch, and in the pouch a heavy gold signet. The boar again. Somebody from the royal house went to a lot of trouble to hide this before the keep fell.', 'A smashed chest under a beam. Looters got here long ago.', '', '', 'sticks', '', ''),
(411, 0, -1757.610, -1666.000, 53.580, 4.9913, 1, 'Perception', 12, '', '', 9001411, 10, 1800, 0, 1, '', 'A heap of skulls - sheep, mostly, and one or two you''d rather not name - outside an ogre''s lean-to.', 'The biggest skull has had its eye-holes stuffed with something shiny.', '', '', 'Coins. Lots of small coins, wedged in the sockets: an ogre''s idea of decoration, or a bank. Either way, it''s yours now.', '', '', '', ''),
(412, 0, -1719.140, -2088.410, 50.716, 5.0508, 0, 'Nature', 11, '', '', 9001412, 10, 0, 6550, 2, '', '', '', 'A herb-gatherer''s fire, with drying racks round it. Most of the herbs have blown away. Her dye-pots are still by the fire, and a box on the rack is sealed with a dyer''s swatch - match it and the seal lifts. Inside, forgotten: a pair of wristguards studded with thorn-spikes, for keeping wolves off while you work.', 'A ring of stones and a smell of burnt leaves.', '', '', 'dye', '', ''),
(413, 0, -1692.980, -2382.040, 37.589, 5.7421, 1, 'Perception', 13, '', '', 9001413, 10, 2400, 0, 1, '', 'Moss-grown stones on a rise, the remains of a shepherd''s hut wall.', 'One stone near the corner sits a fraction proud of the rest.', '', '', 'The shepherd''s savings, in a clay pot behind the stone. They''re long gone, and so are their sheep - the hills are full of things that eat both.', '', '', '', ''),
(414, 0, -1642.030, -2256.390, 31.544, 5.0138, 0, 'Medicine', 12, '', '', 9001414, 10, 600, 4948, 1, '', '', '', 'A Stromgarde soldier, years dead, still in the remains of his tabard. The arrow that killed him is Witherbark. His kit is mostly rot, but his mace is sound - black iron, and it rings like a funeral bell when you lift it. You say a few words over him before you take it.', 'Old bones in a rusted helm. Whatever he carried has gone to rust too.', '', '', '', '', ''),
(415, 0, -1564.030, -2828.720, 39.502, 0.7398, 0, 'Investigation', 13, '', '', 9001415, 10, 1500, 0, 1, 'syndicate_letter', '', '', 'A Syndicate courier''s cart, overturned - the driver gone, the horse gone, the strongbox smashed. But couriers keep the important things in the seat-cushion. Sewn inside it, a letter-case with a lettered clasp, and in that a letter in a careful hand to someone in the Syndicate, about an ogre they are ''educating'': how much gold he pays, how little he''s learning, and how they mean to be rid of him once Stromgarde is theirs. The ogre is named. He would not like what he''s called.', 'An overturned cart. The strongbox is matchwood and empty.', '', '', 'cipher', '', ''),
(416, 0, -1548.480, -2413.470, 76.365, 4.4413, 0, 'Arcana', 13, '', '', 9001416, 10, 1500, 1462, 1, '', '', '', 'A standing stone on the hilltop, with a groove spiralling round it from the ground to the crown. The old highland folk made these to keep their treasures: the stone opens for the song it was carved to - one every Arathi child once knew. Sing it true, and a slab in the base swings out.', 'A tall stone with a spiral groove. The wind hums in it, tunelessly.', '', '', 'song', 'highland_air', ''),
(418, 0, -1484.120, -3282.400, 34.991, 4.8116, 0, 'Sleight of Hand', 15, '', '', 9001418, 10, 1000, 1265, 1, '', '', '', 'A Syndicate dead-drop: a black chest chained to a boulder, with a combination dial that is far too good for an honest box. It takes you a long time. Inside, wrapped in oiled cloth, is a sword - a fine, straight Stromgarde blade, taken from a dead knight and waiting for a buyer. The fence won''t be getting it.', 'The lock is a Gilnean three-tumbler and it beats you. The pick bends.', '', '', 'dial', '', ''),
(419, 0, -1391.160, -2574.250, 84.401, 5.4454, 0, 'Arcana', 13, '', '', 9001419, 10, 800, 0, 1, 'binding_rune', '', '', 'One of the Shadowmages'' marker-stones, from when Dalaran''s cast-offs had their towers in these hills. Its sigils still burn; put every one out and a little stone falls out of a socket in its face: a rune of binding, carved with a mark for ''close'' on one side and ''open'' on the other. It is the key to one of their circles. Which way you set it is up to you.', 'Sigils on an old stone. They prickle under your fingers and don''t do anything.', '', '', 'wards', '', ''),
(420, 0, -1341.480, -2209.720, 61.057, 1.8376, 1, 'Perception', 11, '', '', 9001420, 10, 500, 0, 1, 'wanted_poster', 'A Refuge Pointe patrol''s wagon, burned out by the roadside.', 'A tube of oiled leather has rolled under the axle, out of the fire.', '', '', 'Wanted posters, a dozen, still crisp: a Syndicate highwayman with a crossbow and a pleasant smile, and a large reward in red ink. The patrol was putting them up. Someone stopped them.', '', '', '', ''),
(421, 0, -1326.180, -1700.120, 57.061, 4.3703, 0, 'Survival', 12, '', '', 9001421, 10, 1600, 0, 1, '', '', '', 'A deserter''s camp: a fire pit dug in, so it couldn''t be seen, and a bedroll under a rock. Whoever it was, they kept their coin in their boot. They left in their bare feet.', 'A pit with ash in it. You don''t find anything else.', '', '', '', '', ''),
(422, 0, -1286.130, -2883.840, 49.391, 3.3083, 0, 'Animal Handling', 12, '', '', 9001422, 10, 1900, 0, 1, '', '', '', 'A strider''s nest, built out of a smashed supply crate and an astonishing amount of string. The bird is out. Its eggs are not, and it does not appreciate you. You talk it down from a hiss to a grumble, slowly, and it lets you lift out the one thing in the nest that isn''t an egg: a tin of coins it stole off a cart for the shine.', 'The strider comes back, sees you, and you leave at speed.', '', '', 'knots', '', ''),
(424, 0, -1119.160, -2857.640, 42.488, 2.5311, 1, 'Perception', 12, '', '', 9001424, 10, 300, 0, 1, 'highland_air', 'A broken crate at the edge of the Dabyrie fields, spilling straw.', 'Something wooden and curved is tangled in the straw - not part of the crate.', '', '', 'A shepherd''s whistle-pipe, the old highland kind, with a scrap of paper tied round it: the fingering for ''The Thoradin Air'', the song every Arathi child learned before the kingdom fell. You try it. It''s lovely. The paper adds, in another hand: ''The old ones still open for it.''', '', '', '', ''),
(425, 0, -1129.640, -3713.640, 85.994, 1.4317, 0, 'History', 13, '', 'Dwarf', 9001425, 10, 900, 0, 1, 'echo_horn', '', '', 'A collapsed dwarven air-shaft, from a hall older than the kingdom. In the rubble at its foot, a signal-horn of the old delvers - a long curl of bronze with the mouth flared like a lily. They used these to call each other through the deep halls. The halls are still down there, and a horn like this would sound in them like the mountain itself.', 'Fallen stones and a draught from somewhere below. You can''t shift enough of it.', '', 'A delvers'' shaft - your people dug this. You know exactly where they''d hang the horn.', 'dig', '', ''),
(427, 0, -1096.470, -1773.510, 58.907, 0.4724, 0, 'Animal Handling', 11, '', '', 9001427, 10, 700, 0, 1, '', '', '', 'A strider herder''s camp, long cold, and the herder''s crook leaning on a rock with her notes tied to it: how to tell a strider''s temper from its neck, how to calm it, what it eats. They''re good notes. You read them twice and find you remember them. Wrapped up with them is her pay.', 'Bones of a big bird, and an old crook. Somebody''s flock, once.', '', '', '', '', 'Animal Handling'),
(428, 0, -908.190, -3015.490, 86.773, 4.2237, 0, 'Investigation', 14, '', '', 9001428, 10, 3800, 11965, 1, '', '', '', 'A Shadowmage''s coffer, sunk in the hillside below their old tower. The trap on the lid is a groove of live glyph-wire that would have cost you your eyebrows; you guide a probe down it to the latch behind. Inside: a purse of old Dalaran coin, still bright, and a hunter''s ring carved with running stags.', 'A stone box with a symbol on the lid. You decide, on reflection, not to touch it.', '', '', 'wire', '', ''),
(429, 0, -914.545, -2412.420, 53.414, 1.2917, 0, 'Insight', 11, '', '', 9001429, 10, 1700, 0, 1, '', '', '', 'Two sets of bedrolls by a fire, one on each side - and a line scratched in the dirt between. Two partners who fell out over the share. Their scale is still on the stone, and the share-box under it only opens when the pans hang level. One left in a temper and forgot his half of the purse. The other had already gone.', 'A fire and two bedrolls. Nobody came back for them.', '', '', 'scales', '', ''),
(501, 0, -7291.040, -2118.210, 297.682, 3.7723, 0, 'Survival', 11, '', '', 9001501, 10, 1200, 0, 1, '', '', '', 'A prospector''s mule, crushed flat under a fallen boulder - and the boulder, you notice, has footprints leading away from it. The prospector got clear. His saddlebags didn''t, and they''re just reachable.', 'A mule''s bones under a rock. Something big walks round here, and it doesn''t watch its step.', '', '', 'tracks', '', ''),
(502, 0, -7252.130, -2597.300, 292.227, 3.9444, 1, 'Perception', 12, '', '', 9001502, 10, 2800, 2289, 1, '', 'Red stones split by the sun, in a heap at the foot of a crag.', 'One of them is round as a cannonball, and the cracks in it glitter.', '', '', 'A fire-geode: inside, the stone is lined with tiny orange crystals that seem to hold the heat of the sun. Dwarven jewellers pay well for these, and the Badlands are the only place they turn up. Tucked in with it: a Scroll of Shatter.', '', 'geode', '', ''),
(503, 0, -7199.490, -2282.150, 256.879, 1.3963, 0, 'Investigation', 12, '', '', 9001503, 10, 1600, 0, 1, '', '', '', 'An ogre trophy-pile: skulls of coyotes, buzzards, a cat, and two that were people. Ogres take the head and leave the rest - including the purse on the belt. You find it in the dust under the pile, where it fell.', 'A pile of skulls. You don''t go through them. It doesn''t feel polite.', '', '', '', '', ''),
(504, 0, -7196.890, -3125.940, 288.870, 1.5533, 0, 'History', 13, '', '', 9001504, 10, 1500, 0, 1, 'giants_song', '', '', 'A standing stone carved with dwarven runes so old they''re half earthen: the first delvers set it here when they came to dig under the mountain that lay down. Sing it the delvers'' hymn and it answers - with a slow, low song of its own, cut into the hollow behind its face. It is a lullaby for something very big. You learn it before you know you''re learning it.', 'Weathered runes on a red stone. You can make out the word ''sleep'' and nothing else.', '', '', 'song', 'delvers_hymn', ''),
(506, 0, -7154.020, -3289.230, 246.480, 1.4907, 0, 'Medicine', 12, '', '', 9001506, 10, 700, 12053, 1, '', '', '', 'A Stormwind soldier''s bones, still in his mail, a coyote-gnawed field kit at his side. He died of his wound, not the coyotes - you can see the arrowhead lodged in his ribs. On his hand, a ring as warm as a banked hearth. It did nothing about the arrow.', 'Old bones in old mail. You don''t find anything you''d want to carry.', '', '', '', '', ''),
(507, 0, -7088.370, -2278.620, 268.892, 2.2785, 1, 'Perception', 11, '', '', 9001507, 10, 1400, 0, 1, '', 'A smashed crate with an Ironforge stencil, dragged up here by something with big hands.', 'The ogres took the food. Wedged in a split board is something they didn''t want.', '', '', 'A purse, and a little tin of salve. Ogres can''t count and won''t eat tin.', '', '', '', ''),
(508, 0, -7082.950, -2750.590, 243.051, 4.6077, 0, 'Survival', 13, '', '', 9001508, 10, 3200, 4419, 1, '', '', '', 'Old spoil from a dwarven shaft, filled in long ago and baked hard as brick. Broken up and sifted, it gives back what the diggers threw out with the rubble: a delver''s belt-pouch, with the coins of a king who has been dead two thousand years.', 'The ground is hard as a forge floor. You chip at it and give up.', ' Tucked in with it: a Scroll of Lightning Bolt.', '', 'sift', '', ''),
(509, 0, -7026.890, -3075.780, 241.702, 5.9934, 0, 'Sleight of Hand', 13, '', '', 9001509, 10, 2600, 0, 1, '', '', '', 'A strongbox half buried in the dust - a payroll chest, Ironforge-made, the kind that goes out to dig camps. The dial is stiff with sand, but sand is honest: turn it slowly and the tumblers tell you where they fall. Most of the payroll is gone. Most.', 'Sand in the keyhole, sand in the tumblers, sand in your eyes. The lock wins.', '', '', 'dial', '', ''),
(510, 0, -7011.120, -3925.590, 264.014, 5.1684, 0, 'Survival', 13, '', '', 9001510, 10, 600, 0, 1, 'drake_egg', '', '', 'A hunter''s hide, cut into the bank and covered with a ragged blanket: an egg-thief''s. He''s gone, and in a hurry - his pack is still here, and in the pack, wrapped in wool to keep it warm, is a black egg the size of your head. It is warm. Something inside it moves when you touch it.', 'A hollow in the bank, and an old blanket. Whoever hid here is long gone.', '', '', '', '', ''),
(512, 0, -6955.580, -4102.330, 285.789, -1.5708, 0, 'Arcana', 15, '', '', 9001512, 10, 5000, 5002, 2, '', '', '', 'Amethyst pillars, grown out of the rock by old magic, humming a chord that''s almost music. They were a ward once, the black dragonflight''s. Touch them in the order of the chord and the hum resolves - and the rock at their foot cracks open on a hoard: a small one, by dragon standards. Not by yours.', 'The crystals hum. Your teeth hum with them. Nothing else happens, except a headache.', '', '', 'runes', '', ''),
(513, 0, -6796.370, -2649.540, 244.431, 4.9218, 0, 'Investigation', 11, '', '', 9001513, 10, 500, 0, 1, 'control_rod', '', '', 'A gnome''s toolbox, fallen off a cart and burst open: spanners, springs, a pocket-sized oil can, and a long brass rod with a key-head on the end and a label on it in tiny handwriting - ''SPARE CONTROL ROD, SIEGE MODEL, DO NOT LOSE (AGAIN)''. A little purse is rolled up in a rag at the bottom.', 'A burst box of gnomish bits. You couldn''t tell a spring from a sprocket.', '', '', '', '', ''),
(514, 0, -6895.190, -3382.880, 242.167, 4.1109, 0, 'Religion', 11, '', '', 9001514, 10, 1100, 0, 1, '', '', '', 'A trogg shrine: coyote skulls round a lump of raw iron, the stone they worship. The troggs have left it offerings - things that shine. You leave the iron and take the coins, and say something respectful to the lump before you go.', 'Coyote skulls round a rock. You''d rather not disturb it.', '', '', '', '', ''),
(516, 0, -6794.990, -3219.910, 265.918, 1.4137, 0, 'Investigation', 13, '', '', 9001516, 10, 1200, 0, 1, 'sealed_orders', '', '', 'A Dark Iron courier''s dispatch box, lying in a gully where his mount threw him - long ago, by the rust. The box is sealed with lead against fire and water; a careful heat softens it. Inside: Shadowforge orders, under the Thaurissan seal, for the commander at Angor: ''Abandon the fortress. March the garrison to the Gorge at once.'' The seal was never broken. The orders never arrived.', 'A rusted iron box in a gully. The lock has fused shut.', '', '', 'forge', '', ''),
(517, 0, -6781.940, -3812.130, 264.368, 1.2535, 1, 'Perception', 13, '', '', 9001517, 10, 2400, 0, 1, '', 'Sun-cracked stones on the lip of the ravine, blackened on one side by fire.', 'Behind the scorch-marks the rock has run like wax - and set round something.', '', '', 'A traveller''s purse, caught in a dragon''s breath and sealed into the stone. The leather is ash; the coins are fused together into one lump. Silver is silver, though.', '', '', '', ''),
(518, 0, -6757.960, -2769.660, 242.919, 2.3038, 0, 'Survival', 12, '', '', 9001518, 10, 1500, 0, 1, '', '', '', 'A gnome''s camp-stove, which has exploded. The gnome is fine (the footprints run away very fast). His lunch is not, but his coin-purse landed in a bush thirty feet off.', 'A blackened ring in the dust and a strong smell of burnt oil.', '', '', '', '', ''),
(519, 0, -6731.130, -2966.870, 242.798, 3.9968, 0, 'Medicine', 11, '', '', 9001519, 10, 800, 0, 1, '', '', '', 'A field surgeon''s camp: a stretcher, a bone-saw, and the surgeon''s own notebook, sun-bleached but readable - how to set a bone, draw a tooth, stop a bleed with nothing but a belt and a stick. She wrote well. You read it through twice, sitting in the shade, and when you close it you know it. Her fee-purse is tucked inside the cover.', 'A broken stretcher and some rusted tools. You don''t know what half of them are for.', '', '', '', '', 'Medicine'),
(520, 0, -6649.060, -3482.490, 264.266, 4.3790, 0, 'History', 12, '', '', 9001520, 10, 900, 0, 1, 'hammertoe_map', '', '', 'An Explorers'' League cart, its canvas flapping. The crates have been smashed, and the map under the seat has been torn into squares. Pieced back together: Hammertoe''s survey of the dig, in his own hand - and a second sheet he clearly never meant to leave lying about, marking where the real vault lies, miles from the dig, under the Uldaman road.', 'A wrecked cart. Someone has been through it already, and thoroughly.', '', '', 'slide', '', ''),
(521, 0, -6615.120, -3587.550, 243.647, 2.5931, 1, 'Perception', 12, '', '', 9001521, 10, 400, 0, 1, 'delvers_hymn', 'A League supply crate, stove in, its straw packing blown across the dust.', 'Something under the straw catches the sun: brass, and round.', '', '', 'A delver''s pitch-pipe, the kind dwarven work-gangs used to keep time in the deep halls, and wrapped round it a sheet of music: ''The Delvers'' Hymn''. Somebody has written under it: ''The old stones still answer it.'' You blow a few notes, and the canyon blows them back.', '', 'tune', '', ''),
(522, 0, -6598.350, -2497.140, 272.415, 3.7439, 0, 'Religion', 14, '', '', 9001522, 10, 1000, 0, 1, 'earthen_idol', '', '', 'A buried niche at the foot of an earthen marker-stone, sealed with a plug of fused sand. Inside, a figure of grey stone, no taller than your forearm: one of the makers, the old titan-forged earthen. It is perfectly made and very heavy. Anything that worships stone would worship this.', 'A stone with worn carvings. The ground at its foot is hard as iron.', '', '', 'dig', '', ''),
(524, 0, -6556.670, -3145.330, 260.401, 0.3322, 0, 'Sleight of Hand', 15, '', '', 9001524, 10, 800, 3740, 1, '', '', '', 'A Shadowforge weapon-locker, chained to a rock where a patrol once camped. The lock is Dark Iron work, full of hooks and false gates, and it takes you an age. Inside, wrapped in black oilcloth, is a greatsword - Dark Iron steel, rune-etched along the fuller, still sharp enough to shave with.', 'The lock bites your pick off in the keyhole. Dark Iron work.', '', '', 'lock', '', ''),
(525, 0, -6504.050, -3704.300, 273.491, 3.5802, 0, 'Insight', 11, '', '', 9001525, 10, 1300, 0, 1, '', '', '', 'Two bedrolls by a dead fire, and a game of cups laid out between them, abandoned mid-round: three cups, and the stake under one. The winner left in a hurry - the loser later, and angrier, by the tracks. Nobody took the stakes.', 'A cold fire and an abandoned game. Whoever played it isn''t coming back.', '', '', 'shells', '', ''),
(526, 0, -6459.680, -4017.890, 279.983, 5.8712, 1, 'Perception', 12, '', '', 9001526, 10, 1100, 118, 1, '', 'Scorched skulls - coyote, buzzard, ogre - piled below a whelp''s den in the cliff face.', 'The whelps collect shiny things too. Something glitters up in the den.', '', '', 'A dragon''s idea of a hoard: buckles, a spoon, a dozen coins, and a healing draught the whelps must have thought was a jewel.', '', 'climb', '', ''),
(527, 0, -6448.810, -3112.520, 315.680, 0.0582, 1, 'Perception', 13, '', '', 9001527, 10, 300, 0, 1, 'fire_ale', 'Dark Iron supply crates stacked under an overhang below Angor Fortress, long forgotten.', 'Most of them are empty. One at the back, behind the rest, sloshes.', '', '', 'A keg of Dark Iron fire ale, the real thing, sealed with Shadowforge wax. The smell alone makes your eyes water. A whole keg - enough to put a giant to sleep, or an ogre.', '', 'crates', '', ''),
(529, 0, -6299.710, -3558.400, 251.847, 1.7279, 0, 'Nature', 12, '', '', 9001529, 10, 2200, 0, 1, '', '', '', 'Among the broken rock, one stone is lighter than it should be. You know what that means. You crack it on another: inside, a hollow of smoky quartz, points as long as your finger.', 'Red rocks. Lots of red rocks.', '', '', 'geode', '', ''),
(601, 0, -7142.740, -1523.480, 240.484, 3.2112, 0, 'Survival', 11, '', '', 9001601, 10, 1200, 4385, 1, '', '', '', 'A slave who got away, and got this far. The lava spiders found him. His escape kit is still bundled in his shirt: stolen coins, smoked-glass forge goggles, and a scrap of map with Thorium Point circled.', 'Bones in a scrap of sacking. You don''t want to know what made those marks.', '', '', '', '', ''),
(602, 0, -7128.930, -904.009, 296.198, 0.4383, 0, 'Investigation', 15, '', '', 9001602, 10, 3600, 27502, 1, '', '', '', 'A Dark Iron paymaster''s strongbox, fallen from a cart on the mountain road and wedged between two rocks. The lock is fused by heat. Heat, then, is what opens it: you work it soft again, and it gives.', 'A fused iron box. Whatever''s in it is staying in it.', ' Tucked in with it: a Scroll of Fire Shield.', '', 'forge', '', ''),
(603, 0, -7126.350, -1223.390, 292.527, 2.6176, 1, 'Perception', 12, '', '', 9001603, 10, 3800, 1712, 1, '', 'Slag and cinders heaped against the rock wall, still warm to the touch.', 'Something round is buried in the cinders, much too light to be slag.', '', '', 'Sifted out of the cinders: a fire-opal geode, cracked by the heat - inside, a hollow of milky stone shot through with flashes of red and gold. The Brotherhood''s jewellers would give a lot for it. Tucked in with it: a Scroll of Spirit Guardians.', '', 'sift', '', ''),
(604, 0, -7119.990, -1837.240, 302.177, 4.2374, 1, 'Perception', 13, '', '', 9001604, 10, 1500, 118, 2, '', 'A glassweb spider''s larder: skulls and bones, wrapped in strands that glitter like spun glass.', 'One of the cocoons is the wrong shape - square. A pack, bound in a tangle of glassy strands.', '', '', 'Worked loose: a traveller''s pack, webbed up whole. Inside, untouched: a purse, and two healing draughts.', '', 'knots', '', ''),
(605, 0, -6812.600, -1079.570, 242.737, 6.1419, 0, 'Investigation', 13, '', '', 9001605, 10, 800, 0, 1, 'golem_schematic', '', '', 'A Dark Iron engineer''s crate, dumped by a dead golem: spare plates, a broken gear, and a roll of drawings in an oilcloth tube. A war golem, every rivet of it - the Mark Nine, it says - signed and dated a year ago by a steamsmith named Grimbolt. Somebody''s going to be very upset about this.', 'Scrap iron and broken gears. You cut your finger on something.', '', '', '', '', ''),
(606, 0, -7048.980, -1778.900, 265.257, 5.1271, 0, 'History', 12, '', '', 9001606, 10, 900, 0, 1, 'thorium_vein', '', '', 'A Thorium Brotherhood survey cart, years old, its wheels long gone. In the toolbox under the seat, a vein-map of the Gorge, torn into squares and pieced back together: every seam the Brotherhood ever found, with one marked in red - ''the big one, keep it quiet''. It''s a long way from here.', 'A dead cart and an empty toolbox. Someone got here first.', '', '', 'slide', '', ''),
(607, 0, -7040.060, -1185.060, 255.285, 0.5585, 0, 'Survival', 13, '', '', 9001607, 10, 3000, 0, 1, '', '', '', 'Cinders and ash over something harder - an old miner''s tool-pit, covered over and forgotten. Under the tools, a miner''s savings in a clay jar, and a small, perfect lump of thorium ore.', 'Ash, cinders, and more ash. Your hands come up black.', '', '', 'dig', '', ''),
(609, 0, -6962.380, -1667.710, 241.104, 3.9226, 0, 'Medicine', 12, '', '', 9001609, 10, 1000, 6214, 1, '', '', '', 'A golem-wright, crushed by his own creation, by the look of it. Dark Irons are buried with their tools, but nobody buried him. His maul, though, is intact - and when you lift it, the head glows like a coal.', 'A crushed Dark Iron and a crushed toolbox. Nothing worth taking.', '', '', '', '', ''),
(610, 0, -6907.640, -893.320, 245.551, 0.5934, 0, 'Arcana', 13, '', '', 9001610, 10, 700, 0, 1, 'chain_glyph', '', '', 'A Dark Iron binding-stone, practice work: an apprentice''s copy of the glyphs the forge-masters use to chain fire. Put its glyphs out one by one and the last gives itself away - the whole glyph, written backwards, the way you''d undo it. Somebody was going to be in a lot of trouble for leaving this lying about.', 'Blackened runes on a slab. They''re warm, and they stay that way.', '', '', 'wards', '', ''),
(611, 0, -6937.420, -1396.060, 169.355, 6.0214, 1, 'Perception', 11, '', '', 9001611, 10, 600, 22979, 1, '', 'A burst ore-crate on the Cauldron floor, spilling grey rock.', 'Not all of it''s rock. Something wrapped in cloth is tucked into a corner.', '', '', 'A slave''s hidden stash: a few coins, saved one at a time, and a plain iron ring someone swore kept them alive. You hope they got out.', '', '', '', ''),
(613, 0, -6701.040, -1699.270, 214.545, 1.7977, 0, 'Nature', 12, '', '', 9001613, 10, 2200, 0, 1, '', '', '', 'Rock round a fumarole, cut with channels the Dark Irons used to bleed off its heat, their stones knocked askew. Set running again, the vent cools enough to reach the crust - and in it, little red crystals of cinnabar. Alchemists pay well for it, as long as you don''t lick your fingers.', 'Hot yellow rocks and a terrible smell.', '', '', 'pipes', '', ''),
(614, 0, -6778.220, -1846.360, 260.229, 2.6561, 0, 'Sleight of Hand', 15, '', '', 9001614, 10, 1200, 2256, 1, '', '', '', 'A Thorium Brotherhood strongbox, left behind when an outpost fell, and locked with one of their own puzzle-locks: brass letter-wheels geared each to the next, and the word they want stamped on the hasp. It takes you a long time. Inside, packed in straw, is a mace forged from thorium - dark grey, faintly warm, with the Brotherhood''s hammer stamped on the head.', 'The gears turn, and turn, and click back to the start. The Brotherhood made this to beat you.', '', '', 'cipher', '', ''),
(615, 0, -6769.650, -1607.130, 189.605, 2.4794, 0, 'Arcana', 11, '', '', 9001615, 10, 600, 0, 1, '', '', '', 'A Dark Iron apprentice''s satchel, dropped in the scramble when the fire elementals broke loose: lesson slates, chalk, and a primer of the runes of flame and stone, with notes in the margin in a child''s hand. It''s a good primer. You sit and match the slates'' runes in pairs, and by the end the old signs make sense to you. A few coins were rolled up in the lesson-cloth.', 'A burnt satchel full of broken slates.', '', '', 'pairs', '', 'Arcana'),
(616, 0, -6752.180, -714.348, 237.260, 3.4720, 0, 'Religion', 12, '', '', 9001616, 10, 600, 0, 1, 'doomsday_tract', '', '', 'A Twilight camp-fire, and a bundle of tracts - the scripture they hand out to converts. Most are the usual raving. One page, in a finer hand and plainly from higher up, names the day of the Hour of Twilight - a different day from the one the local highlord has been preaching. And it says, quite clearly, that anyone who preaches otherwise is a heretic and belongs in the fire.', 'Ash, and some burnt pamphlets. You can make out the word ''doom'' quite a lot.', '', '', '', '', ''),
(617, 0, -6737.710, -610.845, 241.217, 2.1119, 0, 'Nature', 12, '', '', 9001617, 10, 2400, 0, 1, '', '', '', 'A thunder-egg in the scree: a dull grey ball of rock that clinks when you shake it. You crack it on a stone. Inside, a star of blue agate and a hollow full of tiny crystals.', 'You crack a lot of rocks. They turn out to be rocks.', '', '', 'geode', '', ''),
(618, 0, -6692.210, -1043.040, 243.047, 0.7854, 1, 'Perception', 12, '', '', 9001618, 10, 900, 118, 1, '', 'A supply crate, half buried in black sand blown down off the ridge.', 'The sand has kept the bottom layer cool. Something''s still packed in there.', '', '', 'A Brotherhood ration-pack: hard bread, and wrapped in a cloth, a healing draught and a small purse.', '', '', '', ''),
(619, 0, -6674.300, -1514.830, 242.878, 4.8939, 1, 'Perception', 11, '', '', 9001619, 10, 1100, 0, 1, '', 'Spider-sucked bones by the trail, half covered in fine grey ash.', 'The ash shifts in the wind and uncovers a glint of metal.', '', '', 'A belt-buckle, and the coins that were in the purse it held up.', '', '', '', ''),
(620, 0, -6627.600, -1317.290, 208.843, 4.8257, 0, 'Sleight of Hand', 13, '', '', 9001620, 10, 1800, 0, 1, 'quota_ledger', '', '', 'An overseer''s lockbox, hidden under a loose slab below the Cauldron''s rim - and the slabs around it are Dark Iron pressure-plates. You pick your way across. Inside, a purse - and a ledger. Two ledgers, in fact: the one the Shadowforge sees, and the real one. Every faked tally, every slave written off, every bar of iron that went into a private pocket. It''s signed ''B.'' The ''B'' has very elaborate curls.', 'A good Dark Iron lock. It wins.', '', '', 'floor', '', ''),
(621, 0, -6596.130, -1570.880, 272.754, 0.0351, 0, 'History', 13, '', 'Dwarf', 9001621, 10, 800, 0, 1, 'keeper_rune', '', '', 'An Explorers'' League marker-stone, from the dig that came here before the Dark Irons drove the League out. Wake its marks in their order and a socket opens in its face: inside, a palm-sized rune of black glass - a keeper''s mark, the kind the League used to bind their guardian-golems to them.', 'A carved stone. The marks are League, you think, but they won''t come clear.', '', 'League marks. Your uncle taught you these; you open it without thinking.', 'runes', '', ''),
(622, 0, -6595.470, -1951.650, 246.016, 2.0246, 1, 'Perception', 12, '', '', 9001622, 10, 500, 0, 1, 'letter_home', 'A dead courier''s fire at the edge of the Gorge, the coals long cold.', 'His satchel is still under the rock where he propped his head. Letters.', '', '', 'A Redridge courier''s mailbag. Most of the letters have been rained on and baked dry again into pulp. One is legible - to a boy who joined some cult and went west, from his mother. There''s a few coins of postage in the bag too.', '', '', '', ''),
(623, 0, -6560.440, -824.799, 297.716, 3.6652, 0, 'Performance', 13, '', '', 9001623, 10, 4000, 0, 1, '', '', '', 'An anvil-stone of the old Thorium Brotherhood, carved before they split from the Dark Irons: they sealed their savings into stones like this, and opened them with the forge-chant. You sing it to the stone, and the stone rings back like an anvil struck - and the seam down its middle opens.', 'A stone shaped like an anvil. You hum at it. It doesn''t hum back.', '', '', 'song', 'forge_chant', ''),
(624, 0, -6470.110, -894.340, 324.171, 6.2483, 0, 'Insight', 11, '', '', 9001624, 10, 700, 0, 1, '', '', '', 'A cultist''s bedroll and a little crate of belongings, hidden behind a rock away from the others, where the camp''s watchman walks with his lantern. You slip in between his rounds. Somebody wanted to keep these to himself: a carved toy horse, a lock of a girl''s hair, and a few Redridge coins. You leave the horse and the hair. The coins, he''ll not need where he''s gone.', 'A bedroll and a box of oddments. Nothing much.', '', '', 'sneak', '', ''),
(625, 0, -6417.640, -1388.790, 139.706, 6.1168, 1, 'Perception', 12, '', '', 9001625, 10, 400, 0, 1, 'forge_chant', 'A Thorium Brotherhood work-crate, its brass bands warped by heat.', 'Inside, among the tongs, something brass that isn''t a tool.', '', '', 'A Brotherhood smith''s tuning-fork, the kind they strike to keep the forge-chant in time, and wrapped round it a sheet of the chant itself, worn soft with handling. ''The old anvil-stones still open for it,'' someone has written underneath. You strike the fork and it rings for a long, long time.', '', 'tune', '', ''),
(626, 0, -6373.710, -1909.900, 273.042, 0.0000, 0, 'Survival', 12, '', '', 9001626, 10, 2000, 0, 1, '', '', '', 'A spider-hunter''s last camp. The spiders won, but not before he''d stashed his bounty - glassweb fangs, worth good silver to an alchemist - in a crack high in the rock, out of their reach - and very nearly out of yours.', 'Bones, webs, and a broken spear. You don''t stay.', '', '', 'climb', '', ''),
(701, 0, -4778.480, -1131.890, 498.802, 4.4500, 0, 'Investigation', 14, '', '', 9001701, 10, 600, 0, 1, 'diamond_shard', '', '', 'A scorch-ring on the stone near the Great Forge''s lip, half swept away - the mark of a ritual circle. Sifted out of the grit in the cracks, where the sweepers missed it: a sliver of something that isn''t stone: diamond, clear as water, and inside it, frozen, the grain of a dwarf''s braided beard. The king isn''t dead. He''s in there.', 'Soot and cracked flagstones. The forge is hard on floors.', '', '', 'sift', '', ''),
(702, 0, -4751.190, -1026.820, 504.515, 0.9774, 0, 'Sleight of Hand', 13, '', '', 9001702, 10, 900, 0, 1, 'guild_hammer', '', '', 'A leatherworker''s strongbox, left behind when the shop was emptied. Under the false bottom someone has hidden something that has nothing to do with leather: a hammer of black iron, its head stamped with the anvil-and-crown of the forgemasters'' guild. It went missing the day the regency took the Forge. Every smith in the city would know it on sight.', 'A stout lock. It isn''t interested in you.', '', '', 'lock', '', ''),
(703, 0, -4858.890, -1056.430, 502.190, 1.1519, 1, 'Perception', 15, '', '', 9001703, 10, 0, 0, 1, 'magni_signet', 'A chip of carved stone, knocked off the throne-room steps in some scuffle and kicked aside.', 'Under it, in the gap between two steps, a glint of gold.', '', '', 'A heavy signet ring: the Bronzebeard anvil, worn smooth by forty years on one hand. The king''s own seal. Someone hid it here the night of the ritual - or it fell, and nobody has dared to look.', '', '', '', ''),
(704, 0, -4963.590, -1014.190, 503.952, 5.2360, 0, 'Sleight of Hand', 14, '', '', 9001704, 10, 1200, 3013, 1, 'true_deed', '', '', 'A clerk''s deed-box on a counting-house dial, left in a hurry when the regency''s men took over the counting-house. Inside, among receipts, a deed under the Bronzebeard seal - the clan''s own, to its halls and mines - signed by Magni himself. Someone saved it from the forger''s sack. Its twin, you''d guess, is being rewritten in the Vault right now.', 'The lock clicks, and clicks, and stays shut.', ' Tucked in with it: a Scroll of Hold Person.', '', 'dial', '', ''),
(705, 0, -4998.680, -1155.700, 501.760, 4.7781, 1, 'Perception', 11, '', '', 9001705, 10, 1100, 0, 1, '', 'A courier''s crate, left where the courier stood, half full of undelivered letters.', 'One of the letters is heavier than the rest.', '', '', 'A letter with coins sewn into the lining - somebody''s wages, sent home and never delivered. The address is a farm in Dun Morogh that was burned last winter. You keep the coins.', '', '', '', ''),
(706, 0, -4964.690, -936.287, 501.743, 5.4454, 0, 'Survival', 12, '', '', 9001706, 10, 1400, 4424, 1, '', '', '', 'A fishing-promoter''s prize box, still full of tackle. The prize - a purse for the biggest fish - was never awarded. The contest was the week the king fell.', 'Fish-hooks and old line. You prick your thumb.', ' Tucked in with it: a Scroll of Mirror Image.', '', '', '', ''),
(707, 0, -4937.980, -993.686, 505.216, 2.0944, 0, 'Religion', 12, '', '', 9001707, 10, 800, 118, 1, '', '', '', 'A small shrine to the Light, set in the wall where a priest once taught. Its tablet only opens to the light: a shaft from the high window, and old mirrors to bring it round. Behind the tablet, the offerings of a hundred apprentices: copper, mostly, and a healing draught left for whoever would need it.', 'A carved tablet of the Light. You say a quiet word, and leave it.', '', '', 'mirror', '', ''),
(708, 0, -4865.230, -865.331, 502.275, 5.0091, 1, 'Perception', 12, '', '', 9001708, 10, 300, 0, 1, 'grim_guzzler_song', 'A reagent-seller''s crate by the inn, the jars long gone.', 'Wedged in the bottom: a battered songbook, not a reagent in sight.', '', '', 'A Dark Iron songbook, of all things - drinking songs from the Grim Guzzler, deep in Blackrock. Someone has marked one: ''the one that makes them cry''. You hum it. It has a terrible, beautiful tune. Somebody has written in the margin: ''the old music-stone in the Mystic Ward knows it too.''', '', 'tune', '', ''),
(709, 0, -4823.650, -1299.360, 501.951, 0.9599, 1, 'Perception', 13, '', '', 9001709, 10, 400, 0, 1, 'cipher_key', 'A quartermaster''s crate near the tram tunnel, its lid prised open and put back.', 'The packing straw has been disturbed - and there''s paper in it.', '', '', 'A strip of parchment covered in letters arranged in a grid, with a word written above each column: a cipher key. Forsaken work, by the hand. Somebody dropped it in a hurry and hid it in the straw, meaning to come back.', '', '', '', ''),
(710, 0, -4802.490, -1248.500, 502.086, 4.4157, 1, 'Perception', 11, '', '', 9001710, 10, 300, 0, 1, 'gnomish_salve', 'An engineer''s supply crate, its lid stencilled with the Gnomeregan cog.', 'Most of it''s been scavenged. A heavy jar is locked in a gnomish puzzle-tray - roll the ball to the catch.', '', '', 'A jar of grey-green salve with a Gnomeregan infirmary label: ''For radiation sickness - apply liberally - DO NOT EAT''. There isn''t much of it in Ironforge. You know a few gnomes who''d weep to see it.', '', 'maze', '', ''),
(711, 0, -4635.110, -1306.360, 503.465, 2.0246, 0, 'History', 14, '', 'Dwarf', 9001711, 10, 500, 0, 1, 'titan_disc', '', '', 'A carved tablet from Uldaman, mounted on the library wall: the League never worked out how to read it. You do. Press the titan-runes in the order the earthen carved them and a stone tray slides out: on it, a disc of bronze no bigger than your palm, covered in runes that seem to move. A maker''s key. Anything earthen would know it.', 'Titan-runes. They sit there, refusing to make sense.', '', 'Earthen runes - your grandmother had a book of these. You read it like a nursery rhyme.', 'runes', '', ''),
(712, 0, -4681.390, -1266.610, 503.382, 2.3562, 0, 'Investigation', 12, '', '', 9001712, 10, 700, 0, 1, '', '', '', 'A Reclaimers'' field chest: brushes, little picks, labels, a practice tablet broken in five for students to fit back together, and the expedition notes of a League archaeologist - how to read strata, date a carving, tell a dwarf''s work from an earthen''s. They''re clear and well written, and by the time you''ve read them through you see the halls around you differently. His dig-fund purse is tucked in the back.', 'A chest of little tools and labels. You can''t tell what half of them are for.', '', '', 'shards', '', 'History'),
(713, 0, -4715.460, -1228.570, 501.743, 1.5882, 0, 'Religion', 11, '', '', 9001713, 10, 900, 0, 1, '', '', '', 'A shrine-stone of the Earthen Ring, left by the shaman who kept it: a ring of carved elements round a hollow for offerings, and little channels cut to bring water from the font to it - their stones knocked askew. Set right, the water runs, the hollow drains, and the offerings are still in it. The elements, you feel, would rather you used them than left them for the Dark Irons.', 'A stone with carvings of fire, water, earth and air. Pretty.', '', '', 'pipes', '', ''),
(714, 0, -4588.630, -1225.200, 503.465, 3.4034, 0, 'Survival', 13, '', '', 9001714, 10, 2800, 0, 1, '', '', '', 'A heap of fallen beams and masonry from the Hall of Explorers'' roof, never cleared. Underneath, crushed flat but intact: an explorer''s pack, and in the pack a purse and a pouch of uncut gems from some far-off dig.', 'Heavy stones. You shift a few and give up.', '', '', 'sticks', '', ''),
(715, 0, -4650.120, -1120.800, 508.634, 1.5708, 0, 'Arcana', 13, '', '', 9001715, 10, 600, 0, 1, 'ritual_page', '', '', 'A crate of reagents abandoned in the Forlorn Cavern - and under them, wrapped in black cloth, a page torn from a ritual book: a circle of binding stone, cast at the Great Forge''s heart, with a name in the centre: MAGNI. Down the margin, the names of the acolytes who stood the circle. One or two of them you''ve seen preaching in this very cavern.', 'Dried herbs and powders. Something in them makes your eyes water.', '', '', '', '', ''),
(716, 0, -4653.320, -896.476, 502.281, 2.4435, 0, 'Arcana', 13, '', '', 9001716, 10, 2000, 858, 1, '', '', '', 'A wand-seller''s display of focusing crystals, left humming in their cradle. They''re still lit: put every one out and the cradle unlocks: underneath, the seller''s takings, and a vial of something restorative.', 'Crystals hum at you. You hum back. Nothing happens.', '', '', 'wards', '', ''),
(717, 0, -4659.200, -944.427, 500.461, 4.2412, 0, 'Performance', 13, '', '', 9001717, 10, 3000, 0, 1, '', '', '', 'An old music-stone, carved before the War of the Three Hammers, when Bronzebeard and Dark Iron still sang the same songs. Sing it the old drinking song and it sings back - and the panel at its base slides open on the gift some long-dead minstrel left for whoever knew the tune.', 'A stone carved with musical notes. You can''t make them out.', '', '', 'song', 'grim_guzzler_song', ''),
(718, 0, -4640.130, -1014.640, 501.650, 3.3289, 1, 'Perception', 12, '', '', 9001718, 10, 1000, 3472, 1, '', 'A gnome''s fruit-cart crate, abandoned in the Mystic Ward, the fruit long gone to mush.', 'Under the rot, a cash-tin, sealed.', '', '', 'The fruit-seller''s takings - and, oddly, a pair of smith''s gauntlets left in her keeping, still warm to the touch. She left in a hurry, the day the regent came.', '', '', '', ''),
(719, 0, -5042.060, -1205.560, 509.001, 0.9774, 0, 'Sleight of Hand', 15, '', '', 9001719, 10, 1000, 2244, 1, '', '', '', 'The weapon master''s own locker, behind the training racks - a guard captain''s lock, three tumblers and a false gate. It takes a long time. Inside, oiled and wrapped, is a longsword in the Ironforge guard''s pattern, its blade etched with the Bronzebeard anvil. It is a very good sword.', 'A guard captain''s lock. It was made to beat people exactly like you.', '', '', 'lock', '', ''),
(720, 0, -4969.460, -1180.240, 501.743, 3.2463, 0, 'Insight', 12, '', '', 9001720, 10, 1600, 0, 1, '', '', '', 'A leather-collector''s crate, still half full - and a note to her apprentice: ''Hide the money where the regent''s men won''t look. They never look at the dirty hides.'' You shift the stacked bales of dirty hides until the one at the bottom comes free.', 'A crate of stinking leather. You''d rather not dig through it.', '', '', 'crates', '', ''),
(721, 0, -4986.590, -1034.190, 501.652, 1.3327, 0, 'Investigation', 12, '', '', 9001721, 10, 2200, 0, 1, '', '', '', 'A loose stone in the wall by the Stonecutters'' hall, chiselled out and put back. Behind it, the Defias'' stash - stolen coin, wrapped in a stonemason''s apron with the red bandana tucked inside.', 'Old stonework. Very well laid. Nothing loose.', '', '', '', '', ''),
(722, 0, -4790.140, -1168.660, 502.312, 4.8426, 1, 'Perception', 11, '', '', 9001722, 10, 800, 3556, 1, '', 'A pie-seller''s crate in Tinker Town, the smell of old crust lingering.', 'One pie-tin is heavier than the others - and the rats of Tinker Town know it.', '', '', 'The pie-seller''s savings, baked into a pie-tin for safe keeping. Ingenious. Also a perfectly good pie.', '', 'rats', '', ''),
(801, 0, -8470.000, 361.367, 116.809, 0.6390, 0, 'Investigation', 14, '', '', 9001801, 10, 800, 0, 1, 'dragon_scale', '', '', 'A cracked flagstone in the Keep''s hall where the Royal Guard used to stand. Something heavy has dragged across it, again and again, scoring deep grooves - claws, not boots. Wedged in the deepest groove: a black scale as long as your hand, still faintly warm. No lizard grows a scale like this. Nothing small does.', 'Scuffed flagstones. The Keep sees a lot of boots.', '', '', '', '', ''),
(802, 0, -8532.000, 392.070, 108.386, 0.6740, 1, 'Perception', 13, '', '', 9001802, 10, 400, 0, 1, 'lescovar_letter', 'A courier''s satchel, left under the stair where a Royal Guard once stood watch.', 'The stair is still watched by lantern. Between its sweeps you reach the satchel: searched, but not well - a letter is sewn into the strap.', '', '', 'A letter in a nobleman''s elegant hand, never sent: ''My friends of the Brotherhood - the Keep''s watch changes at the ninth bell, and the Lady''s soldiers do not walk the garden wall -'' It''s signed with a G and a flourish. Lord Gregor Lescovar''s garden is just up the steps.', '', 'sneak', '', ''),
(803, 0, -8927.760, 481.330, 93.943, 1.7104, 0, 'Sleight of Hand', 13, '', '', 9001803, 10, 900, 0, 1, 'sealed_dispatch', '', '', 'A field marshal''s dispatch box on a combination dial, left behind when the old commanders were sent north. Among the orders, a packet that doesn''t belong: a Dark Iron seal, black anvil and crown, unbroken. Addressed to the Regent of Ironforge''s envoy in Stormwind. It''s been sitting here a week.', 'A good lock. A soldier''s lock. It wins.', '', '', 'dial', '', ''),
(804, 0, -8955.320, 523.414, 96.440, 3.7874, 1, 'Perception', 11, '', '', 9001804, 10, 1200, 4422, 1, '', 'A recruiting officer''s crate by the Valley of Heroes, full of unsigned enlistment papers.', 'Under the papers, the recruiting bounty nobody came to collect.', '', '', 'A purse of enlistment bounties, never paid out: the Lady stopped recruiting the week she took the throne. You keep it. The papers you leave for the wind. Tucked in with it: a Scroll of Haste.', '', '', '', ''),
(805, 0, -8885.250, 614.395, 95.358, 3.5256, 0, 'Sleight of Hand', 12, '', '', 9001805, 10, 1500, 4425, 1, '', '', '', 'A guild master''s strongbox, abandoned when the guild offices were shut by the Lady''s order. Guild dues, never collected.', 'The lock sticks. Guild locks always do.', ' Tucked in with it: a Scroll of Dispel Magic.', '', 'lock', '', ''),
(806, 0, -8886.150, 679.911, 100.180, 2.1282, 1, 'Perception', 12, '', '', 9001806, 10, 300, 0, 1, 'stormwind_anthem', 'A wine-seller''s crate outside the shuttered tasting-room, empty bottles rattling in the straw.', 'Rolled in one of the bottles: a sheet of music.', '', '', 'The old Stormwind anthem - the one they sang when the city was rebuilt, before the nobles refused to pay the masons and nobody felt like singing any more. You hum it. It''s a fine, proud tune. In the margin: ''the Cathedral bell-stone rings it, if you know how''.', '', 'tune', '', ''),
(807, 0, -8824.280, 665.711, 97.467, 0.5411, 0, 'Investigation', 12, '', '', 9001807, 10, 1300, 0, 1, '', '', '', 'An auctioneer''s lot-box, the tickets spilled and the unsold lots all jumbled. Matched up again, most are junk; one is a little purse of old silver, lot forty-one, reserve never met.', 'Junk. Lots and lots of junk.', '', '', 'pairs', '', ''),
(808, 0, -8519.000, 797.796, 106.519, 0.7400, 0, 'Investigation', 13, '', '', 9001808, 10, 600, 0, 1, 'wage_ledger', '', '', 'A reagent-seller''s chest by the Cathedral steps, and in its false bottom, hidden by a sympathetic brother of the Light: the Stonemasons'' Guild''s wage-ledger - the city''s own copy, every page sealed by the treasury. On the last page, in a clerk''s neat hand: ''Payment refused by order of the Lord Protector.''', 'Candles, incense, and a lot of dust.', '', '', '', '', ''),
(809, 0, -8547.720, 814.663, 106.530, 3.8530, 0, 'Religion', 12, '', '', 9001809, 10, 800, 3314, 1, '', '', '', 'A small shrine in the Cathedral''s shadow, set in the wall. The carved stone only opens to the light: turn the old mirrors until the sun from the high window falls on it. Behind it, the offerings of the faithful: copper and silver, and a pair of fine gloves left with a prayer for a gentler tongue.', 'A carved memorial stone. You say a quiet word, and leave it.', '', '', 'mirror', '', ''),
(810, 0, -8546.000, 845.796, 106.601, 4.7300, 0, 'Athletics', 13, '', '', 9001810, 10, 1600, 0, 1, '', '', '', 'A heap of fallen masonry from the Cathedral''s unfinished north wall - the masons downed tools the day the pay stopped. Lifting the fallen scaffold beams aside, you find a mason''s lunch-tin, and in it a mason''s savings: two years of them.', 'The stones won''t shift. Whoever built this built it well.', '', '', 'sticks', '', ''),
(811, 0, -8512.000, 862.364, 109.927, 3.8220, 0, 'Performance', 15, '', '', 9001811, 10, 1800, 4947, 1, '', '', '', 'The old bell-stone beside the Cathedral doors - the one the masons set when the city was rebuilt. Sing it the anthem and the stone sings back, deep and clear, the whole square ringing with it; and a panel at its base swings open on the masons'' own offering, sealed in when the stone was laid.', 'The bell-stone is silent. It wants a song, and not just any song.', '', '', 'song', 'stormwind_anthem', ''),
(812, 0, -8752.300, 377.572, 101.139, 1.2915, 1, 'Perception', 14, '', '', 9001812, 10, 500, 0, 1, 'shaw_cipher', 'A night-watchman''s crate in an Old Town alley, a lantern and a cold cup of tea on its lid.', 'The crate has a false lid. SI:7 likes false lids.', '', '', 'A brass cipher-wheel, the kind SI:7 uses for its dead drops - and a note in Shaw''s own hand on how to read one. You turn the wheel and the alleys of Old Town start making a different kind of sense.', '', 'cipher', '', 'Insight'),
(813, 0, -8660.310, 381.223, 104.451, 2.2689, 0, 'Sleight of Hand', 15, '', '', 9001813, 10, 1000, 7466, 1, 'bartleby_ring', '', '', 'A blade-merchant''s strongbox, hidden behind the shuttered shop, its lid rigged with a spring-blade on a wire. Past it, wrapped in velvet, a ring of red gold - not a merchant''s ring. A noble''s. A ward against harm is worked into the band. Below it, a plain little wedding band, much worn, with ''B. & M.'' inside it - someone''s pawned it here.', 'The lock is better than the shop was. It holds.', '', '', 'wire', '', ''),
(814, 0, -8670.600, 427.464, 100.992, 0.9599, 0, 'Medicine', 11, '', '', 9001814, 10, 700, 10638, 1, '', '', '', 'A poison-seller''s sample case, abandoned. Its tray only lifts when the three vials on it balance - you decant them to their marks, very carefully. Under it, folded small: a dark cloak that makes no sound at all when it moves.', 'Little bottles with skulls on. You put them down, carefully.', '', '', 'pour', '', ''),
(815, 0, -8692.720, 397.438, 101.370, 5.5189, 1, 'Perception', 11, '', '', 9001815, 10, 900, 0, 1, '', 'A loose cobble in an Old Town lane, rocking under your boot.', 'There''s a hollow under it, and in it a child''s marble-tray with a catch at one end. Old Town''s full of them.', '', '', 'A street-child''s treasure-hole: marbles, a tin soldier, and a surprising amount of silver, probably not honestly come by. You leave the marbles.', '', 'maze', '', ''),
(816, 0, -8965.000, 808.006, 109.546, 1.2780, 0, 'Arcana', 13, '', '', 9001816, 10, 700, 0, 1, 'binding_sigil', '', '', 'A cluster of humming crystals left where a hatter had his stall - a ward-anchor, and one of its anchors is a sigil of black iron stamped with the Kirin Tor''s eye. A binding sigil, the kind that shuts a summoning circle''s open door.', 'The crystals hum at you. You don''t hum back properly.', '', '', 'runes', '', ''),
(817, 0, -8866.000, 822.286, 98.400, 0.5760, 0, 'Investigation', 12, '', '', 9001817, 10, 500, 0, 1, 'stockade_key', '', '', 'A librarian''s book-chest near the Stockade. Under the books, someone has hidden a big iron key with a warden''s tag: STOCKADE - MAIN. The warden''s own, stolen the night of the breakout and hidden here by someone who never came back for it.', 'Books. Heavy ones.', '', '', '', '', ''),
(818, 0, -8887.000, 985.503, 124.541, 4.6770, 0, 'Investigation', 11, '', '', 9001818, 10, 1100, 0, 1, '', '', '', 'A fireworks-seller''s crate, the rockets long gone. In the bottom, the takings from the last festival before the Lady cancelled them all.', 'Burnt paper and the smell of powder.', '', '', '', '', ''),
(819, 0, -8756.840, 972.561, 98.887, 1.0646, 0, 'History', 12, '', '', 9001819, 10, 1200, 0, 1, '', '', '', 'A carved stone by the park, half hidden in ivy: a memorial to the dead of the city''s burning, with a hollow behind it where the families left coins for the masons who rebuilt their homes. The masons were never paid. The coins are still here.', 'A memorial stone, too worn to read.', '', '', '', '', ''),
(820, 0, -8469.000, 582.931, 96.051, 5.3760, 1, 'Perception', 12, '', '', 9001820, 10, 1000, 0, 1, '', 'A dwarven gunsmith''s crate, stencilled with the Bronzebeard anvil.', 'Under the gun-oil rags, a bundle of letters from Ironforge.', '', '', 'Letters home that never went: a gunsmith writing to her brother in Ironforge, telling him to get out before the Anvilrage come. Folded into the last of them, a little purse of savings for his passage.', '', '', '', ''),
(821, 0, -8463.900, 1109.410, 19.135, 1.4835, 0, 'Athletics', 13, '', '', 9001821, 10, 1700, 0, 1, '', '', '', 'A ship''s chest left on the quay, too heavy for one sailor to lift - and too heavy for you, nearly. Once you''ve levered the nails out of the lid: a sea-captain''s pay, and a bottle of very good rum.', 'It doesn''t budge. Whatever''s in there is staying in there.', '', '', 'pry', '', ''),
(822, 0, -8549.760, 1245.420, 5.330, 5.1600, 0, 'Survival', 11, '', '', 9001822, 10, 600, 0, 1, '', '', '', 'A fisherman''s crate on the lower quay, lines and hooks and a tin of good bait. You drop a line off the quay and hook something heavy: a sunken net-bag, and in it a little purse for whoever mends the nets.', 'Fish-hooks. Ow.', '', '', 'fish', '', ''),
(901, 0, -10104.000, 687.487, 31.994, 0.0000, 0, 'Sleight of Hand', 15, '', '', 9001901, 10, 1400, 1214, 1, 'riverpaw_totem', '', '', 'A farmer''s strongbox, dragged off by gnolls and dumped when it wouldn''t open. You manage what they couldn''t. Inside: the farm''s savings - and wrapped in sacking, a gnoll''s spiked mace taken off a dead raider, heavy and wicked and very well balanced. And under it all, a skull-and-feather totem, old and mended many times: the Riverpaw''s own, from before Hogger.', 'The lock has beaten gnolls. It beats you too.', '', '', 'lock', '', ''),
(902, 0, -9983.970, 568.819, 37.763, 0.0000, 0, 'Investigation', 12, '', '', 9001902, 10, 1100, 4421, 1, '', '', '', 'A peddler''s chest, abandoned at the forest''s edge when the gnolls came. Most of the stock is ruined. The cash box isn''t, and its dial still turns.', 'Rain-swollen wood and ruined ribbons.', ' Tucked in with it: a Scroll of Revivify.', '', 'dial', '', ''),
(903, 0, -9866.260, 221.780, 14.034, -2.7402, 1, 'Perception', 12, '', '', 9001903, 10, 500, 0, 1, 'big_candle', 'A miner''s chest, deep in Fargodeep, from before the kobolds took the mine.', 'Under the old tools, wrapped in oilcloth, something white.', '', '', 'A candle. A real Goldshire candle - fat, white, never lit, the kind the miners kept for emergencies. To a kobold, this is worth more than gold. You can think of a kobold or two who''d agree.', '', '', '', ''),
(904, 0, -9828.590, 87.250, 0.875, -0.4712, 0, 'Sleight of Hand', 14, '', '', 9001904, 10, 1300, 778, 1, '', '', '', 'A foreman''s strongbox at the bottom of Fargodeep, its lock drowned in candle-wax. Warmed soft, it gives. Inside, the mine''s last payroll - and the foreman''s own pick, steel-headed and keen, far too good for a kobold.', 'Candle-wax in the lock. Kobolds.', '', '', 'forge', '', ''),
(905, 0, -9729.420, 656.299, 31.834, 2.3562, 0, 'Investigation', 11, '', '', 9001905, 10, 900, 0, 1, '', '', '', 'A quartermaster''s barrel near the Westbrook garrison, half full of rainwater. At the bottom, in a sealed tin, a soldier''s back pay.', 'Rainwater and a drowned spider.', '', '', '', '', ''),
(906, 0, -9880.300, -189.318, 35.126, 1.4592, 0, 'Investigation', 13, '', '', 9001906, 10, 600, 0, 1, 'defias_orders', '', '', 'A Defias campfire, cold, and the camp struck in a hurry. In the ashes, half burned, a sheet of orders in VanCleef''s own hand: collectors to be ''retired'' for theft from the Brotherhood. The first name on the list is Morgaine''s.', 'Ash and bones and a red bandana.', '', '', '', '', ''),
(907, 0, -9748.020, -25.264, 35.407, 3.9668, 0, 'History', 13, '', '', 9001907, 10, 1500, 1711, 1, '', '', '', 'A weathered runestone from the days of the Arathi kings, older than Stormwind. The old words still read true, and the stone''s hollow keeps an old offering: silver, black with age.', 'Moss and weathered carving. The words won''t come.', ' Tucked in with it: a Scroll of Hypnotic Pattern.', '', 'runes', '', ''),
(908, 0, -9508.270, -762.008, 60.299, 1.5454, 0, 'Arcana', 13, '', '', 9001908, 10, 700, 0, 1, 'azora_seal', '', '', 'A cluster of humming crystals in the wood below the Tower of Azora - a ward-marker, set by Theocritus''s apprentices. Its glyphs still burn; put them out and, tucked in its heart: a wax seal of the Tower, and a letter, never sent, to two apprentices who left: ''Come home. All is forgiven. Bring the good teapot.''', 'The crystals hum, and you get a headache.', '', '', 'wards', '', ''),
(909, 0, -9547.140, -449.578, 60.449, 2.8264, 1, 'Perception', 11, '', '', 9001909, 10, 300, 0, 1, 'murloc_charm', 'A cairn of moss-grown stones on the shore of Crystal Lake, arranged with care.', 'The stones are a murloc shrine. Its offering has been knocked into the lake: you can see it glint on the bottom.', '', '', 'A fin-charm: shells and river-pearls braided on a cord of weed, sacred to somebody. Murlocs left it here. Murlocs would want it back, very much.', '', 'dive', '', ''),
(910, 0, -9483.030, -433.494, 58.355, -0.7505, 1, 'Perception', 12, '', '', 9001910, 10, 400, 0, 1, 'shepherds_air', 'A shepherd''s chest on the lake shore, his crook leaning against it.', 'Inside, under the blanket, a wooden pipe and a scrap of written music.', '', '', 'A shepherd''s air - the tune Elwynn''s shepherds whistle to bring the flock home. You try it on the pipe. It''s an old, sweet, lilting thing. In the margin: ''the singing stone by Goldshire knows it''.', '', 'tune', '', ''),
(911, 0, -9630.970, -53.883, 44.632, 1.6406, 0, 'Survival', 11, '', '', 9001911, 10, 1000, 0, 1, '', '', '', 'A hunter''s crate in the hills, his traps neatly stowed. A purse for the season''s pelts.', 'Traps. You nearly lose a finger.', '', '', '', '', ''),
(912, 0, -9625.720, 209.416, 47.985, 2.7348, 0, 'Nature', 12, '', '', 9001912, 10, 500, 6558, 1, '', '', '', 'Old bones under a spider-web tangle - a deer, long ago. Tangled in the web with it - and only picked free strand by strand - a thick leather girdle - lost by whoever tried to wrestle the spider, by the look of it.', 'Bones and webs. You back away from the webs.', '', '', 'knots', '', 'Nature'),
(913, 0, -9460.340, 280.899, 53.024, 0.0000, 0, 'Investigation', 12, '', '', 9001913, 10, 1200, 0, 1, '', '', '', 'A traveller''s chest, robbed and dumped by the road. The robbers missed the double bottom.', 'Empty. Robbed, and robbed thoroughly.', '', '', '', '', ''),
(914, 0, -9471.690, 560.812, 58.018, 0.3840, 0, 'Athletics', 12, '', '', 9001914, 10, 1400, 0, 1, '', '', '', 'A heap of moss-grown stones over an old copper seam. You crack the biggest open: a geode, glittering inside, worth a good deal to a Goldshire jeweller.', 'The stones won''t crack. Your hands will.', '', '', 'geode', '', ''),
(915, 0, -9753.300, -845.746, 39.371, 0.0524, 0, 'Survival', 11, '', '', 9001915, 10, 1300, 0, 1, '', '', '', 'Between the pumpkin rows at Brackwell, freshly turned earth. Somebody buried a crock here - the farmer''s savings, hidden from the Defias. The farmer never came back for it.', 'Pumpkins. Lots of pumpkins.', '', '', 'dig', '', ''),
(916, 0, -9796.160, -929.679, 39.133, 5.8818, 0, 'Sleight of Hand', 12, '', '', 9001916, 10, 1000, 0, 1, '', '', '', 'A farmhand''s chest behind the Brackwell barn, nailed shut against his brothers. Wages, and a bottle of pumpkin wine.', 'The lock''s rusted solid.', '', '', 'pry', '', ''),
(917, 0, -9711.930, -943.498, 38.416, 3.0892, 1, 'Perception', 13, '', '', 9001917, 10, 1100, 0, 1, '', 'A chest half sunk in the mud beside the southern road.', 'Something glints in the mud beside it.', '', '', 'A purse that fell off a Defias cart, and the cart never stopped for it.', '', '', '', ''),
(918, 0, -9764.020, -1261.390, 45.795, 0.3199, 0, 'Survival', 13, '', '', 9001918, 10, 1200, 0, 1, '', '', '', 'A prowler''s trail, and at the end of it the den, empty now - and among the old bones, a lost traveller''s pack, his purse still in it.', 'Bones. Wolf-gnawed bones. You don''t stay.', '', '', 'tracks', '', ''),
(919, 0, -9380.640, -1262.960, 56.987, 2.8449, 0, 'Athletics', 12, '', '', 9001919, 10, 1500, 0, 1, '', '', '', 'A broken lumber cart at the Eastvale camp, its axle snapped. Lifting the spilled lumber off it one log at a time, you find the strongbox the carter hid underneath - the camp''s wages.', 'It''s a very heavy cart.', '', '', 'sticks', '', ''),
(920, 0, -9346.750, -864.965, 66.568, 0.5783, 0, 'Investigation', 11, '', '', 9001920, 10, 900, 0, 1, '', '', '', 'A drover''s cold campfire. He left in a hurry, and left his purse in his bedroll.', 'Ash, and a burnt sausage.', '', '', '', '', ''),
(921, 0, -9354.600, -675.024, 67.373, 5.0057, 0, 'Athletics', 13, '', '', 9001921, 10, 1300, 0, 1, '', '', '', 'Kobold spoil-heap stones near Jasperlode. Sifted through, the spoil gives up one stone that rings hollow - a geode the kobolds threw out because it had no candle in it.', 'Rocks. Kobold-chewed rocks.', '', '', 'sift', '', ''),
(922, 0, -9383.590, 331.037, 58.953, 3.9123, 0, 'Performance', 15, '', '', 9001922, 10, 1800, 1406, 1, '', '', '', 'An old standing stone in the woods by Goldshire, hollowed by wind. Whistle the shepherd''s air into it and it whistles back, every note - and the moss falls away from a niche in its side, where the shepherds of a hundred years have left their thanks.', 'The stone is silent. It wants a tune, and not just any tune.', '', '', 'song', 'shepherds_air', ''),
(923, 0, -8957.040, -432.748, 64.719, -3.0543, 1, 'Perception', 12, '', '', 9001923, 10, 400, 0, 1, 'vineyard_deed', 'A crate of stolen books dumped behind the Northshire vineyard.', 'Most are prayer books. One is a ledger, with a deed tucked in it.', '', '', 'The vineyard''s deed, under the Abbey''s seal, made over to the old vintner''s daughter. The Brotherhood told her she''d lost it. She didn''t. Somebody would very much like to see this.', '', '', '', ''),
(924, 0, -9100.110, -1033.550, 72.885, -2.8798, 0, 'Sleight of Hand', 15, '', '', 9001924, 10, 2000, 6537, 1, '', '', '', 'A rogue wizard''s chest in the woods, sealed with a groove of biting ward-wire round the catch. Past it: a spell-seller''s takings, and a pair of boots that feel lighter than air.', 'The ward bites. You let go.', '', '', 'wire', '', ''),
(925, 0, -8900.410, -770.323, 69.553, -2.4260, 0, 'Investigation', 11, '', '', 9001925, 10, 1000, 0, 1, '', '', '', 'Supply crates dropped by the Riverpaw on the eastern road, piled every which way. Slid apart, the one at the bottom holds stolen goods - including a merchant''s purse.', 'Gnoll-chewed straw.', '', '', 'crates', '', ''),
(926, 0, -8986.670, -1251.840, 76.454, 5.7153, 0, 'Investigation', 15, '', '', 9001926, 10, 2200, 0, 1, '', '', '', 'Fish bones and broken spears where the Stone Cairn murlocs feast. Washed out of the midden in the lake shallows - the murlocs'' hoard: rings, buttons, coins, every shiny thing they''ve taken from a fisherman for years.', 'Fish bones. The smell follows you for an hour.', '', '', 'pan', '', ''),
(927, 0, 1736.600, 41.854, -59.234, 2.0595, 0, 'Sleight of Hand', 14, '', '', 9001927, 10, 2000, 10306, 1, 'bethor_journal', '', '', 'A Kirin Tor travelling chest, its violet paint flaking, its ward still faintly lit. Inside, wrapped in a rotted robe: a little leather journal, a student''s, the name on the flyleaf ''B. Iceshard, apprentice to Archmage Antonidas''. Lecture notes, a list of books, and a page of very bad poetry.', 'Dalaran made good locks. This one still is.', ' Tucked in with it: a Scroll of Blight.', '', 'wards', '', ''),
(928, 0, 1813.740, 56.414, -47.304, 3.0543, 1, 'Perception', 12, '', '', 9001928, 10, 2500, 27498, 1, '', 'A cluster of focusing crystals on a warlock''s shelf, humming to themselves in the dark.', 'Two of the crystals have come loose. They''d sing true, if somebody tuned them.', '', '', 'Two focusing crystals, tuned true at last, and the purse that was hidden beneath them - the price of a warlock''s lessons, never collected. Tucked in with it: a Scroll of Death Ward.', '', 'tune', '', ''),
(929, 0, 1711.590, 57.167, -62.206, 4.8869, 1, 'Perception', 11, '', '', 9001929, 10, 800, 9088, 2, '', 'A reagent seller''s crate, the labels in a spidery Forsaken hand.', 'Behind the crate: a rack of flasks, two of them half filled, the measure-lines scratched on.', '', '', 'Topped up to the lines: two Elixirs of the Grave Ward, the reagent seller''s own stock - bottled courage against the touch of the dead and the bite of poison. The Forsaken drink them to keep their own rot at bay.', '', 'pour', '', ''),
(930, 0, 1500.110, 53.030, -62.410, 2.3500, 0, 'Investigation', 13, '', '', 9001930, 10, 1500, 0, 1, 'plague_orders', '', '', 'A courier''s satchel, dragged into the drain by the Undercity''s rats - and one of them still has the packet, its seal broken. Apothecarium orders: ''Subjects for the third trial, to report for their weekly warding: Deathstalker Agents -'' and a column of names. Somebody in the Rogues'' Quarter didn''t want these delivered.', 'Crates, straw, and the smell of oil.', '', '', 'rats', '', ''),
(931, 0, 1457.910, 69.346, -62.202, 4.4157, 0, 'Stealth', 12, '', '', 9001931, 10, 1200, 0, 1, '', '', '', 'You slip past the old training post''s tripwires without a sound and find what the Deathstalkers leave for anyone quiet enough to reach it: a battered drill-book of the queen''s knives - how to stand, how to wait, how to not be there - and a purse. You read it through twice. It sticks.', 'A board creaks underfoot. Whatever''s in that chest, it isn''t for clumsy feet.', '', '', 'wire', '', 'Stealth'),
(932, 0, 1485.350, 160.439, -60.682, 2.2682, 1, 'Perception', 13, '', '', 9001932, 10, 900, 16005, 2, '', 'An engineer''s barrow, abandoned, loaded with cogs and copper tubing.', 'Packed in sawdust under the tubing: a little row of clay jars.', '', '', 'Two jars of alchemist''s fire, carefully stoppered - the engineers'' answer to anything that won''t stay dead. Throw, and stand well back.', '', '', '', ''),
(933, 0, 1486.120, 208.881, -62.069, 4.9742, 0, 'Religion', 14, '', '', 9001933, 10, 1500, 18500, 1, '', '', '', 'A pile of skulls, arranged - somebody''s shrine to the Light, hidden here by a priest who fell and rose and couldn''t quite let go. The runes cut into the brows answer in the right order, and the shrine gives up its treasure: a ring of silvered elven work, cool to the touch, that the dead''s chill can''t get through.', 'The runes stay dark. Whatever the priest believed, you don''t know the words.', '', '', 'runes', '', ''),
(934, 0, 1564.760, 209.601, -43.019, 0.7679, 0, 'Investigation', 14, '', '', 9001934, 10, 1800, 0, 1, 'ravenholdt_coin', '', '', 'A general-goods crate with a false bottom. In the hollow: a black coin, a raven stamped on both faces, and a note in a careful hand - ''For the man by the Apothecarium doors, if he needs reminding who he works for.'' Ravenholdt''s mark.', 'Candles, rope, a dead rat. Nothing worth the trouble.', '', '', '', '', ''),
(935, 0, 1635.400, 223.331, -43.020, 2.8449, 0, 'Sleight of Hand', 12, '', '', 9001935, 10, 2200, 0, 1, 'census_page', '', '', 'The innkeeper''s dial-locked strongbox, left behind when the city was emptied. Under the takings: a sheaf of census pages, filled in and stamped with the Royal Overseer''s own seal - spares the innkeeper kept for guests who needed to be counted in a hurry. One is blank but for the stamp.', 'The lock bites back. Innkeepers know their guests.', '', '', 'dial', '', ''),
(936, 0, 1635.400, 144.883, -62.055, 6.0388, 1, 'Perception', 12, '', '', 9001936, 10, 600, 0, 1, 'human_locket', 'A book dealer''s crate of mouldering volumes, spilled across the step.', 'Something small and gold falls out of a hollowed-out prayer book.', '', '', 'A gold locket on a broken chain. Inside, two little painted faces: a young woman in a schoolmistress''s collar, and a girl. On the back: ''Andorhal - for Selina, from her girls''.', '', '', '', ''),
(937, 0, 1524.950, 171.353, -62.067, 3.9095, 0, 'Medicine', 11, '', '', 9001937, 10, 900, 1710, 1, '', '', '', 'A field surgeon''s kit from the old Lordaeron army, the instruments wrapped in oilcloth and a manual of battlefield medicine tucked in the lid. You read it cover to cover. Some of it you''ll never forget.', 'Rusted saws and stained bandages. You can''t make sense of the kit.', '', '', '', '', 'Medicine'),
(938, 0, 1514.810, 238.436, -62.078, 1.8114, 1, 'Perception', 11, '', '', 9001938, 10, 500, 0, 1, 'lordaeron_lullaby', 'A memorial stone set into the wall of the lower ring, the names worn almost smooth.', 'Under the names, scratched later and smaller: a line of music.', '', '', 'Lordaeron''s old lullaby, the one every child in the kingdom fell asleep to - four notes, rising and falling. You hum it. Someone has written underneath: ''the bell in the crypt by the canal still knows it.''', '', '', '', ''),
(939, 0, 1529.360, 357.607, -61.417, 4.9916, 0, 'Performance', 13, '', '', 9001939, 10, 2500, 11925, 1, '', '', '', 'A crypt bell, green with age, in a niche by the canal. Struck in the right order it rings out the old lullaby - and the niche behind it slides open. Somebody hid their best things here when Lordaeron fell: a hood of grey wool that makes the dark seem a little less dark, and a purse.', 'The bell clangs, tuneless. The niche stays shut.', '', '', 'song', 'lordaeron_lullaby', ''),
(940, 0, 1527.930, 310.864, -62.062, 2.5656, 1, 'Perception', 10, '', '', 9001940, 10, 1400, 0, 1, '', 'An odds-and-ends seller''s crate, still half full of junk.', 'Rattling around in a tin box: a few coins.', '', '', 'Somebody''s change, forgotten. It spends the same.', '', '', '', ''),
(941, 0, 1550.340, 151.732, -62.092, 4.3284, 0, 'Investigation', 15, '', '', 9001941, 10, 1500, 1711, 1, '', '', '', 'A poison seller''s chest, false-bottomed, false-bottomed again, the last catch keyed to a colour: mix the dyes to match the stain on its lid. In the last hollow, wrapped in lead foil: a scroll of the old Lordaeron court mages, sealed - Hypnotic Pattern, a weave of colours that stops a room dead - and the poison seller''s savings.', 'A poison seller''s chest. You decide not to put your hands in it after all.', '', '', 'dye', '', ''),
(942, 0, 1667.690, 172.243, -62.069, 4.6949, 1, 'Perception', 13, '', '', 9001942, 10, 700, 2514, 5, '', 'A heap of bones swept into a corner of the lower ring.', 'The bones have been sorted - and among them, a quiver.', '', '', 'A Farstrider''s quiver, the leather cracked, with five arrows still in it: their heads are wrapped in oil-soaked cloth that catches the moment it''s loosed. Arrows of fire.', '', '', '', ''),
(943, 0, 1681.910, 285.452, -62.055, 1.7453, 0, 'Athletics', 12, '', '', 9001943, 10, 1600, 6832, 1, '', '', '', 'A smith''s crate nailed shut, the crowbar left lying on top of it as if in apology. Inside: a cloak of oiled grey cloth folded on a smith''s apron, and his week''s takings. The Forsaken smiths wore these at the quench-tank, against the fumes.', 'The crowbar won''t budge, and neither will the lid.', '', '', 'pry', '', ''),
(944, 0, 1685.330, 421.181, -62.215, 1.8675, 0, 'Investigation', 14, '', '', 9001944, 10, 1800, 0, 1, 'dreadlord_letter', '', '', 'A footlocker in the War Quarter barracks, past the night watch and his lantern, with a letter tucked in its lining. It''s in a dreadlord''s hand, addressed to ''my brother Balnazzar'', and it lays out, very calmly, how the Banshee Queen will be betrayed and when - and who will sit on her throne afterwards. It was never sent. Perhaps the writer thought better of it. Perhaps the courier did.', 'Spare boots and a whetstone. A soldier''s footlocker.', '', '', 'sneak', '', ''),
(945, 0, 1653.950, 367.087, -60.682, 4.9393, 1, 'Perception', 12, '', '', 9001945, 10, 800, 3825, 2, '', 'An armourer''s crate with the War Quarter''s mark burnt into the lid.', 'Packed in straw at the bottom: two flasks that slosh heavily.', '', '', 'Two Elixirs of Vigour, the Deathstalkers'' issue before a long night - they put something like life back into you for a while.', '', '', '', ''),
(946, 0, 1478.900, 445.545, -62.614, 1.3614, 0, 'Sleight of Hand', 15, '', '', 9001946, 10, 2500, 0, 1, 'plague_formula', '', '', 'An Apothecarium document case, locked three ways. Inside: a single page of the new plague''s formula - and pinned to it, the queen''s own orders for it, in her elegant hand. Stormwind first. Then the Forsaken who argue with her. Then anyone she finds tiresome. The Master Apothecary''s name is on the list.', 'The third lock defeats you, and the case is too heavy to carry off.', '', '', 'lock', '', ''),
(947, 0, 1543.310, 362.002, -62.160, 3.7263, 1, 'Perception', 11, '', '', 9001947, 10, 600, 13180, 2, '', 'A crate of empty vials outside a shuttered apothecary''s stall.', 'Not all of them are empty.', '', '', 'Two vials of holy water, confiscated from some unlucky priest and never destroyed. The Apothecaries kept them as a curiosity. They burn the dead like fire.', '', '', '', ''),
(948, 0, 1326.720, 358.623, -63.579, 3.9444, 0, 'Investigation', 13, '', '', 9001948, 10, 1200, 0, 1, 'quel_thalas_ribbon', '', '', 'Fallen masonry in a corner of the Royal Quarter. Under the fallen beams and stone, as if dropped by someone drifting past and never picked up: a ranger''s ribbon, the blue of Quel''Thalas, faded nearly white.', 'Stones. The Royal Quarter is crumbling, slowly, like everything else here.', '', '', 'sticks', '', ''),
(949, 0, 1258.260, 289.543, -63.579, 0.7854, 0, 'Religion', 13, '', '', 9001949, 10, 2000, 13209, 1, 'lordaeron_ash', '', '', 'Under the fallen stones, the old chapel of the royal palace: an altar of the Light, its carved face broken in pieces on the floor. Fitted back together, it opens its reliquary: a pouch of ash - the consecrated ash of Lordaeron''s priests, blessed when the kingdom still had a king. The dead who haunt these halls won''t touch it. And a silver seal of the Order of the Silver Hand, its edge still bright.', 'The runes stay cold. The Light, here, is a long way off.', '', '', 'shards', '', ''),
(950, 0, 1306.300, 276.605, -63.577, 1.8675, 1, 'Perception', 15, '', '', 9001950, 10, 4000, 13445, 1, '', 'Bones heaped against the wall of the Royal Quarter, gnawed.', 'Among them, something that isn''t bone: a pouch, heavy. Between you and it, the floor is set with pressure-plates.', '', '', 'Somebody who came this far, and no farther. Their pouch is still full: a royal treasury''s worth of old Lordaeron gold, and a stoppered elixir.', '', 'floor', '', ''),
(951, 1, -1474.760, -81.372, 161.185, 5.7596, 0, 'Survival', 13, '', '', 9001951, 10, 1500, 10310, 1, 'white_feather', '', '', 'A hunter''s drying rack, bones and hides - and caught on a splinter, a single tail-plume, long and perfectly white: a plainstrider''s, from a beast nobody on the rise has ever brought down. Under the rack, a hunter''s tally-book, years of notes on tracking. You read it through.', 'Bones and old hides. Whatever hunted here, it''s long gone.', ' Tucked in with it: a Scroll of Stoneskin.', '', 'tracks', '', 'Survival'),
(952, 1, -1407.810, -82.245, 159.018, 0.9076, 1, 'Perception', 12, '', '', 9001952, 10, 700, 2517, 5, '', 'A fletcher''s crate by the training ground, arrows sticking out of the straw.', 'Most are practice shafts. Five are not.', '', '', 'Five arrows with heads of blue ice that never melts - a tauren hunter''s answer to things too fast to catch. Arrows of ice.', '', '', '', ''),
(953, 1, -1381.290, -75.981, 160.602, 3.1940, 0, 'Investigation', 15, '', '', 9001953, 10, 3200, 27500, 1, '', '', '', 'A battlemaster''s dial-locked chest, abandoned when the city emptied. Under the old banners, the pay for a whole company of braves, never handed out.', 'Banners and old orders. Nothing worth taking.', ' Tucked in with it: a Scroll of Black Tentacles.', '', 'dial', '', ''),
(954, 1, -1326.400, 92.293, 130.717, 5.7615, 1, 'Perception', 13, '', '', 9001954, 10, 600, 0, 1, 'hearth_carving', 'A cairn of sun-cracked stones at the edge of the central rise.', 'Something small and carved, half buried in the sand drifted between the stones.', '', '', 'Sifted out of the sand: a little carved hearthstone, the kind tauren children make for their mothers, with a name scratched into the bottom: ''Pala''. It''s been out here in the wind a long, long time.', '', 'sift', '', ''),
(955, 1, -1283.920, 84.361, 128.870, 1.0123, 0, 'Athletics', 12, '', '', 9001955, 10, 1200, 0, 1, 'stonehoof_hammer', '', '', 'A weaponsmith''s crate, nailed shut. You lever the nails out. Under the spearheads: an old forge hammer, the haft worn smooth by generations of hands, the head stamped with the Stonehoof mark.', 'The nails hold. Tauren nails always do.', '', '', 'pry', '', ''),
(956, 1, -1272.730, 75.387, 128.153, 0.4014, 0, 'Sleight of Hand', 13, '', '', 9001956, 10, 1500, 19535, 1, '', '', '', 'An Argent Dawn courier''s strongbox, left behind when the Dawn''s people fled the rise. Inside: dispatches, a purse, and a scout''s medallion on a leather thong, worn by someone who walked a very long way and noticed everything on the road.', 'The Dawn''s locks are blessed, or stubborn. This one wins.', '', '', 'lock', '', ''),
(957, 1, -1243.760, 47.368, 127.220, 5.9865, 1, 'Perception', 11, '', '', 9001957, 10, 800, 3825, 2, '', 'An armour merchant''s crate, mail rings spilling out of it.', 'Tucked among the rings: two stoppered flasks.', '', '', 'Two Elixirs of Vigour - the merchant''s own, for the long days at the stall. They put something like a second wind into you.', '', '', '', ''),
(958, 1, -1243.530, 158.164, 133.630, 3.6652, 1, 'Perception', 12, '', '', 9001958, 10, 900, 10562, 2, '', 'A miner''s barrow, loaded with ore and blasting gear.', 'Under the ore, wrapped in oilcloth: two clay pots.', '', '', 'Two pots of smokepowder, the miners'' blasting charge. Throw one and stand well back.', '', '', '', ''),
(959, 1, -1176.120, 157.615, 134.812, 3.9619, 1, 'Perception', 11, '', '', 9001959, 10, 500, 0, 1, 'earthmother_chant', 'A runestone outside a sage''s lodge, carved with the Earth Mother''s symbols.', 'Under the symbols, cut more lightly: a line of music.', '', '', 'The Earth Mother''s chant, the one the tauren sing at dawn - four slow notes, rising like the sun. You hum it. Someone has written beside it: ''the wind-chimes on the Elder Rise still remember''.', '', '', '', ''),
(960, 1, -1163.940, 59.486, 145.878, 6.0214, 0, 'Investigation', 13, '', '', 9001960, 10, 1400, 19089, 1, '', '', '', 'A leatherworker''s chest with a false bottom. In it, wrapped in soft hide: a belt of kodo leather, stitched with the old patterns that are meant to make the wearer hard to bring down, and the leatherworker''s savings.', 'Hides and thread. Good work, nothing more.', '', '', '', '', ''),
(961, 1, -1146.210, 83.477, 145.949, 4.2412, 1, 'Perception', 13, '', '', 9001961, 10, 500, 0, 1, 'kodo_carving', 'A crate of offcuts and whittling scraps by a leatherworker''s bench.', 'Among the scraps, something carved by a child.', '', '', 'A little kodo calf, whittled by a child''s knife, the legs uneven. On the belly, cut carefully: ''For father - B.''', '', '', '', ''),
(962, 1, -1145.670, 22.571, 145.363, 0.9076, 1, 'Perception', 10, '', '', 9001962, 10, 1500, 0, 1, '', 'A fruit seller''s crate, the fruit long gone.', 'Her scale is still on the crate, a sealed weight in one pan - and the coin-box under it only opens when the pans hang level.', '', '', 'A fruit seller''s takings, forgotten in the hurry.', '', 'scales', '', ''),
(963, 1, -1131.180, -4.709, 143.644, 0.0873, 0, 'Nature', 12, '', '', 9001963, 10, 1000, 0, 1, '', '', '', 'A herbalist''s chest of pressed plants, each with its name and use in a careful hand - a lifetime''s learning of the plains'' green things. You match each pressed leaf to its label, one by one, and most of it stays with you.', 'Dried leaves. You can''t tell one from another.', '', '', 'pairs', '', 'Nature'),
(964, 1, -1119.670, 47.103, 141.528, 4.7822, 0, 'Arcana', 13, '', '', 9001964, 10, 1500, 10786, 1, '', '', '', 'An enchanter''s runestone. The runes light in the right order, and a little niche opens in its base: a pair of soft moccasins, enchanted so the wind can''t knock you down and the ground goes quickly under you.', 'The runes stay dark.', '', '', 'runes', '', ''),
(965, 1, -1080.810, 30.109, 140.910, 3.6827, 0, 'Sleight of Hand', 12, '', '', 9001965, 10, 1200, 13454, 1, '', '', '', 'An alchemist''s case, its catch a balance of three glass vials: fill each to its mark and it lets go. Inside, padded in wool, the master''s best: an Elixir of Clarity, and her purse.', 'The lock is stiff and the case is heavy.', '', '', 'pour', '', ''),
(966, 1, -1069.230, -17.522, 140.548, 2.6180, 1, 'Perception', 12, '', '', 9001966, 10, 2500, 0, 1, '', 'A cluster of spirit-stones at the rise''s edge, humming in the wind.', 'Two of the stones have come loose. They''d sing true, if somebody tuned them.', '', '', 'Two spirit-stones, tuned true at last, and the offerings left beneath them.', '', 'tune', '', ''),
(967, 1, -980.841, 287.174, 138.084, 4.4331, 0, 'Investigation', 14, '', '', 9001967, 10, 2000, 0, 1, 'grimtotem_ledger', '', '', 'A strongbox hidden under one of the Elder Rise''s boards - which one is marked only on an old star chart pinned beside them. Inside, a ledger in a crabbed old hand: letters to every Grimtotem warband from Stonetalon to Feralas, and one date, underlined three times - ''the night the old bull falls''. Signed with a black totem.', 'Loose boards and dust.', '', '', 'stars', '', ''),
(968, 1, -992.405, 320.615, 142.329, 0.3316, 0, 'Performance', 14, '', '', 9001968, 10, 2500, 19588, 1, 'stillwind_totem', '', '', 'Wind-chimes of bone and stone, hung on a post at the Elder Rise''s edge. Struck in the right order they ring out the Earth Mother''s chant - and the post''s hollow base opens. Inside, a totem carved with the four winds asleep: the stillwind totem, that the shamans set out when the gales off the mesa grow too strong. And a talisman of the same stone, cool and quiet.', 'The chimes clatter, tuneless, and the post stays shut.', '', '', 'song', 'earthmother_chant', ''),
(969, 1, -998.998, 208.718, 106.477, 2.6545, 0, 'Investigation', 13, '', '', 9001969, 10, 1400, 0, 1, 'apothecary_recall', '', '', 'A courier''s satchel in the caves under the Spirit Rise. Inside, a letter sealed with the Royal Apothecary Society''s mark, addressed to ''Apothecary Zamah, Thunder Bluff'': her recall, signed by the Master Apothecary himself. It never reached her.', 'An empty satchel.', '', '', '', '', ''),
(970, 1, -948.744, 248.392, 97.230, 3.6128, 1, 'Perception', 13, '', '', 9001970, 10, 800, 0, 1, 'cenarion_seed', 'Bones and feathers by the Pools of Vision, laid out like an offering.', 'Something that glints silver has rolled from them into the pool - on the bottom, out of an arm''s reach.', '', '', 'A silver-skinned acorn from the Moonglade, still faintly warm with its magic - a gift of the Cenarion Circle, left here as an offering to the spirits.', '', 'dive', '', ''),
(971, 1, -1256.150, -130.285, 162.974, 4.4331, 1, 'Perception', 12, '', '', 9001971, 10, 900, 1710, 1, '', 'A crate fallen from the high rise, caught on a ledge below its edge.', 'Wrapped in a blanket, something squat and red. It''s a long climb down to it.', '', '', 'A Potion of Superior Healing, the kind the Honor Guard carry. Someone forgot theirs.', '', 'climb', '', ''),
(972, 1, -1219.570, -12.697, 165.945, 5.3756, 0, 'Sleight of Hand', 15, '', '', 9001972, 10, 3000, 2103, 3, '', '', '', 'A cook''s spice chest with a very good lettered clasp. Under the spices, someone''s secret: three arrows with black heads, the kind the hunters keep for the beasts that don''t die - Arrows of Slaying - and a fat purse.', 'The lock defeats you. It smells wonderful, though.', '', '', 'cipher', '', ''),
(976, 1, 1583.800, -4473.310, 8.056, 3.7001, 1, 'Perception', 10, '', '', 9001976, 10, 1500, 27501, 1, '', 'An armour seller''s crate in the Valley of Strength, empty but for straw.', 'A purse is caught in the straw at the bottom.', '', '', 'An armour seller''s takings, forgotten in the rush when the city emptied. Tucked in with it: a Scroll of Phantasmal Killer.', '', '', '', ''),
(977, 1, 1633.940, -4445.620, 15.733, 4.8695, 1, 'Perception', 12, '', '', 9001977, 10, 400, 0, 1, 'orphan_doll', 'A crate of lost things behind the inn - left-behind cloaks, a broken lantern, a single boot.', 'Under the cloaks, something small and soft.', '', '', 'A rag doll with button eyes and a tiny wooden axe sewn to its hand. Stitched on its back, in a child''s clumsy thread: ''GROMMY''. Somebody small is missing this very badly.', '', '', '', ''),
(978, 1, 1612.980, -4427.430, 11.434, 2.7667, 1, 'Perception', 12, '', '', 9001978, 10, 800, 6373, 2, '', 'A merchant''s crate on the inn steps, stamped with a flame.', 'Packed in sand inside: two flasks, cool to the touch.', '', '', 'Two Elixirs of Fire Ward. Orgrimmar''s merchants keep them for the summer, and for the Cleft.', '', '', '', ''),
(979, 1, 1595.760, -4174.400, 39.767, 2.7227, 0, 'Insight', 12, '', '', 9001979, 10, 1200, 0, 1, '', '', '', 'A healer''s chest, and inside, between the bandages, the healer''s notebook: not remedies, but faces - how a grunt looks when he''s hiding a wound, how a liar holds her hands, how grief sits in the shoulders. Years of watching people. You match its sketches to their tells, page by page, and you start to see it too.', 'Bandages and salves. Nothing you can make sense of.', '', '', 'pairs', '', 'Insight'),
(980, 1, 1580.050, -4097.680, 36.568, 5.1836, 1, 'Perception', 13, '', '', 9001980, 10, 600, 0, 1, 'runthak_medal', 'Old bones and a rusted helm under a staff merchant''s awning.', 'Something iron glints among the bones.', '', '', 'An old campaign medal on a rotten ribbon: the Horde crest, and on the back, ''Runthak - Hillsbrad''. It''s been lying here for a very long time.', '', '', '', ''),
(981, 1, 1641.650, -4197.520, 56.483, 5.4122, 0, 'Sleight of Hand', 13, '', '', 9001981, 10, 1500, 18505, 1, '', '', '', 'A quartermaster''s footlocker, locked tight. Inside, confiscated goods: a cutpurse''s belt with a dozen hidden pockets, sewn so cleverly the pockets never bulge, and a purse that was certainly not the quartermaster''s.', 'Good iron and a good lock.', '', '', 'lock', '', ''),
(982, 1, 1667.620, -4463.760, 20.391, 1.7104, 0, 'Sleight of Hand', 15, '', '', 9001982, 10, 4500, 10308, 1, '', '', '', 'The auction house''s strongbox, on a combination dial cut for a goblin''s patience. Unclaimed sales, three months of them.', 'Goblin locks. You''d need a goblin.', ' Tucked in with it: a Scroll of Banishment.', '', 'dial', '', ''),
(983, 1, 1735.910, -4452.660, 37.128, 4.3975, 1, 'Perception', 12, '', '', 9001983, 10, 700, 3029, 5, '', 'A scout''s kit bag on a ledge above the Drag.', 'It''s too high to reach, but a stone or two would knock it down. Five arrows rattle inside.', '', '', 'Five arrows whose heads are little glass vials of acid. The scouts call them armour-eaters.', '', 'sling', '', ''),
(984, 1, 1744.900, -4317.860, 33.637, 4.2237, 0, 'Investigation', 14, '', '', 9001984, 10, 1800, 10307, 1, 'burning_blade_sigil', '', '', 'A pile of skulls behind a reagent stall - not decoration: the Burning Blade''s mark is painted inside every one. The biggest is warded, fel glyphs burning in its sockets. Put out, it gives up what''s inside, wrapped in black cloth: an iron flame on a chain. The cult''s own token, the kind its leaders carry.', 'Skulls. The Drag sells odd things.', ' Tucked in with it: a Scroll of Vitriolic Sphere.', '', 'wards', '', ''),
(985, 1, 1775.100, -4482.910, 45.747, 2.1817, 1, 'Perception', 11, '', '', 9001985, 10, 500, 0, 1, 'warsong_dirge', 'A runestone in the Drag, carved with the Warsong clan''s wolf.', 'Under the wolf, scratched later: a line of music.', '', '', 'The Warsong dirge, the one the clan beat on the drums for Grom Hellscream - four heavy notes. You hum it. Beside it someone has scratched: ''the old drum in the Valley of Honor still answers it''.', '', '', '', ''),
(986, 1, 1792.650, -4565.390, 23.106, 0.9774, 1, 'Perception', 11, '', '', 9001986, 10, 800, 3825, 2, '', 'A tailor''s crate of bolts of cloth.', 'Wrapped in a bolt of red silk: two flasks.', '', '', 'Two Elixirs of Vigour, the tailor''s cure for long nights at the loom.', '', '', '', ''),
(987, 1, 1836.770, -4461.590, 47.698, 1.5010, 0, 'Investigation', 13, '', '', 9001987, 10, 1600, 0, 1, 'hellscream_pendant', '', '', 'A trophy chest in a lodge above the Drag, its lid bound to the lodge drum - beat the warband''s rhythm and it lets go. Among the tusks and teeth, one wrapped with care: a tusk pendant on a worn thong, carved with the Warsong wolf. Grom Hellscream''s, by the old tag tied to it - taken from his body after Demon Fall Canyon, and never given to his son.', 'Tusks and teeth. Somebody liked hunting.', '', '', 'drum', '', ''),
(988, 1, 1848.010, -4564.890, 25.087, 1.4137, 0, 'Sleight of Hand', 12, '', '', 9001988, 10, 1200, 20261, 1, '', '', '', 'A leatherworker''s chest with a lettered clasp. Inside, her finest work: a belt of raptor hide, light and supple, made for running. And her purse.', 'The lock sticks.', '', '', 'cipher', '', ''),
(989, 1, 1886.460, -4415.860, 11.960, 3.7699, 0, 'Investigation', 13, '', '', 9001989, 10, 1200, 0, 1, 'darkspear_mask', '', '', 'A crate of troll goods by the Valley of Wisdom''s stair. Under the beads and charms: an old spirit mask, painted in faded Darkspear colours, carried off the Echo Isles when the tribe was driven out.', 'Beads and charms.', '', '', '', '', ''),
(990, 1, 1904.760, -4460.690, 53.521, 2.8623, 1, 'Perception', 12, '', '', 9001990, 10, 2500, 0, 1, '', 'A shaman''s spirit-stones on a high ledge, humming in the wind.', 'Two of them have come loose. They''d sing true, if somebody tuned them.', '', '', 'The stones settle into one low note, and the wind on the ledge drops with them. Wedged in the rock where they stood: a grunt''s offering to the spirits of the air - a pouch of coin, wrapped in a strip of red cloth.', '', 'tune', '', ''),
(993, 1, 1936.760, -4407.650, 21.895, 1.7752, 1, 'Perception', 13, '', '', 9001993, 10, 800, 0, 1, 'spirit_totem', 'Bones and feathers bound together at the foot of the Valley of Wisdom, an old shaman''s offering.', 'In the middle of it, tangled in the cords that bind the rest, a little totem.', '', '', 'A wind-totem of feathers and bone, the knots tied by an old hand - the kind a shaman makes once and keeps for life. Whoever made it isn''t here to want it back.', '', 'knots', '', ''),
(998, 1, 1971.180, -4259.460, 32.443, 4.0143, 0, 'Investigation', 15, '', '', 9001998, 10, 3500, 9187, 1, '', '', '', 'A festival vendor''s chest, and on its lid his cups game, still set up: three cups, and the key under one. Inside, false-bottomed: In the hollow: a purse of old festival takings and an Elixir of Quickness the vendor kept for the races.', 'Paper lanterns and old ribbons.', '', '', 'shells', '', ''),
(991, 1, 1914.160, -4775.870, 36.582, 1.1170, 1, 'Perception', 13, '', '', 9001991, 10, 900, 2103, 3, '', 'A bowyer''s crate of unstrung bows.', 'At the bottom, a quiver with three black arrows in it.', '', '', 'Three Arrows of Slaying, the bowyer''s own, kept for the beasts that don''t die.', '', '', '', ''),
(992, 1, 1915.390, -4645.540, 30.413, 5.2324, 1, 'Perception', 12, '', '', 9001992, 10, 900, 16005, 2, '', 'A goblin''s handcart, loaded with crates marked ''FRAGILE'' and ''DO NOT DROP''.', 'One crate has come open - and the goblins have rigged it: a wire runs from the lid to two jars. Ease them out along it.', '', '', 'Two jars of alchemist''s fire. The goblins label them ''party favours''.', '', 'wire', '', ''),
(994, 1, 1989.310, -4655.910, 27.772, 0.1571, 0, 'Arcana', 13, '', '', 9001994, 10, 1500, 19096, 1, '', '', '', 'A runestone in the Valley of Honor. The runes light in order, and a niche in its base opens: a pendant of Frostwolf work, the white wolf''s head in silver, cold to the touch - the kind the Frostwolf clan give to those who''ve stood the winter with them.', 'The runes stay dark.', '', '', 'runes', '', ''),
(995, 1, 2018.950, -4729.000, 26.101, 1.9373, 1, 'Perception', 11, '', '', 9001995, 10, 800, 10562, 2, '', 'A fireworks seller''s crate, mostly spent rockets.', 'Two pots at the bottom are very much not spent.', '', '', 'Two pots of smokepowder, packed for a festival that never came. Throw, and stand well back.', '', '', '', ''),
(996, 1, 2084.960, -4623.770, 58.920, 0.1571, 0, 'Investigation', 14, '', '', 9001996, 10, 1800, 0, 1, 'fordring_letter', '', '', 'A footlocker in a lodge high above the Valley of Honor, the stair long gone - you climb the rock to it - belonging to someone who never collected it. Inside, under the spare boots: a letter in a firm human hand, addressed ''To Eitrigg, Orgrimmar'' and signed ''T. F.''. It''s been opened, read, folded and refolded many times - and lost.', 'Spare boots and a whetstone.', '', '', 'climb', '', ''),
(997, 1, 2067.860, -4598.880, 54.566, 5.0266, 0, 'Performance', 14, '', '', 9001997, 10, 2500, 19539, 1, 'earthmother_stone', '', '', 'Under the stones, an old war-drum, its hide cracked. Beaten in the right order it booms out the Warsong dirge - and the drum''s hollow body splits open. Inside, wrapped in wolf-fur: a smooth grey stone carved with the Earth Mother''s eye, that the shamans say quiets the ground when it wants to shake, and a fetish of bone bound with spirit-charms against demons.', 'The drum thuds, tuneless. Nothing opens.', '', '', 'song', 'warsong_dirge', '');

